-- TickShow combined Supabase bootstrap.
-- Generated by `npm run db:bundle`; edit migrations and regenerate instead of editing this file.
-- Safe to re-run: all migrations use IF NOT EXISTS / IF EXISTS or CREATE OR REPLACE where needed.

-- ===== 0001_extensions_and_enums.sql =====
-- Phase 1 / 0001: extensions and constrained enum values.
-- Idempotent: safe to re-run; never drops existing objects.
-- gen_random_uuid() is built into PostgreSQL 13+ (Supabase), so no extension is required.

DO $migration$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'app_role') THEN
    CREATE TYPE public.app_role AS ENUM ('admin', 'organizer', 'staff', 'customer');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'account_status') THEN
    CREATE TYPE public.account_status AS ENUM ('active', 'suspended');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'approval_status') THEN
    CREATE TYPE public.approval_status AS ENUM ('pending', 'approved', 'rejected');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'organizer_status') THEN
    CREATE TYPE public.organizer_status AS ENUM ('pending', 'active', 'suspended');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'event_status') THEN
    CREATE TYPE public.event_status AS ENUM ('draft', 'pending', 'published', 'rejected', 'cancelled', 'completed');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'ticket_type_status') THEN
    CREATE TYPE public.ticket_type_status AS ENUM ('draft', 'active', 'paused', 'archived');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'inventory_reservation_status') THEN
    CREATE TYPE public.inventory_reservation_status AS ENUM ('pending', 'confirmed', 'released', 'expired', 'cancelled');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'order_status') THEN
    CREATE TYPE public.order_status AS ENUM ('pending', 'paid', 'failed', 'cancelled', 'refunded', 'expired');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'payment_status') THEN
    CREATE TYPE public.payment_status AS ENUM ('pending', 'processing', 'succeeded', 'failed', 'cancelled', 'refunded', 'partially_refunded');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'payment_method') THEN
    CREATE TYPE public.payment_method AS ENUM ('card', 'bkash', 'nagad', 'bank_transfer', 'other');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'refund_status') THEN
    CREATE TYPE public.refund_status AS ENUM ('pending', 'processing', 'succeeded', 'failed');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'payout_status') THEN
    CREATE TYPE public.payout_status AS ENUM ('pending', 'in_transit', 'paid', 'failed', 'cancelled');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'commission_status') THEN
    CREATE TYPE public.commission_status AS ENUM ('pending', 'settled', 'waived');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'ticket_status') THEN
    CREATE TYPE public.ticket_status AS ENUM ('valid', 'used', 'cancelled', 'refunded', 'expired');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'checkin_status') THEN
    CREATE TYPE public.checkin_status AS ENUM ('not_checked_in', 'checked_in', 'void');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'checkin_result') THEN
    CREATE TYPE public.checkin_result AS ENUM ('success', 'denied', 'reversed');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'organizer_staff_role') THEN
    CREATE TYPE public.organizer_staff_role AS ENUM ('manager', 'checkin', 'sales', 'support', 'analyst');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'event_staff_permission') THEN
    CREATE TYPE public.event_staff_permission AS ENUM ('view', 'checkin', 'manage_orders');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'review_status') THEN
    CREATE TYPE public.review_status AS ENUM ('pending', 'approved', 'rejected');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'notification_type') THEN
    CREATE TYPE public.notification_type AS ENUM (
      'order_created', 'payment_succeeded', 'payment_failed', 'ticket_issued',
      'event_published', 'event_cancelled', 'refund_issued', 'payout_paid', 'system'
    );
  END IF;
END
$migration$;

-- ===== 0002_identity_and_organizers.sql =====
-- Phase 1 / 0002: identity, roles and organizer ownership.
-- Auth is NOT implemented here; profiles are designed to mirror auth.users rows.

CREATE TABLE IF NOT EXISTS public.profiles (
  id uuid PRIMARY KEY REFERENCES auth.users (id) ON DELETE CASCADE,
  full_name text,
  email text,
  avatar_url text,
  phone text,
  status public.account_status NOT NULL DEFAULT 'active',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT profiles_email_format CHECK (
    email IS NULL OR email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
  ),
  CONSTRAINT profiles_phone_format CHECK (phone IS NULL OR length(phone) <= 32)
);

COMMENT ON TABLE public.profiles IS 'User-facing profile data keyed by auth.users.id. No authentication logic lives in Phase 1.';

CREATE TABLE IF NOT EXISTS public.roles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name public.app_role NOT NULL UNIQUE,
  description text,
  is_system boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- Configuration data, not sample/business data. Safe to repeat.
INSERT INTO public.roles (name, description)
VALUES
  ('admin', 'Platform administrator with full controlled access'),
  ('organizer', 'Event organizer account owner'),
  ('staff', 'Event/organizer staff member with explicit assignments'),
  ('customer', 'Ticket buyer')
ON CONFLICT (name) DO NOTHING;

CREATE TABLE IF NOT EXISTS public.user_roles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES public.profiles (id) ON DELETE CASCADE,
  role_id uuid NOT NULL REFERENCES public.roles (id) ON DELETE RESTRICT,
  assigned_by uuid REFERENCES public.profiles (id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT user_roles_user_role_key UNIQUE (user_id, role_id)
);

COMMENT ON TABLE public.user_roles IS 'Role assignments are writable only through public.assign_user_role/remove_user_role, never through direct client DML.';

CREATE TABLE IF NOT EXISTS public.organizers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  owner_id uuid NOT NULL REFERENCES public.profiles (id) ON DELETE RESTRICT,
  slug text NOT NULL UNIQUE,
  name text NOT NULL,
  description text,
  logo_url text,
  contact_email text,
  contact_phone text,
  website_url text,
  address text,
  status public.organizer_status NOT NULL DEFAULT 'pending',
  approval_status public.approval_status NOT NULL DEFAULT 'pending',
  approved_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT organizers_slug_format CHECK (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  CONSTRAINT organizers_name_not_blank CHECK (length(btrim(name)) > 0),
  CONSTRAINT organizers_contact_email_format CHECK (
    contact_email IS NULL OR contact_email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
  ),
  CONSTRAINT organizers_approval_consistency CHECK (
    (approval_status = 'approved' AND approved_at IS NOT NULL) OR
    (approval_status <> 'approved' AND approved_at IS NULL)
  ),
  CONSTRAINT organizers_active_requires_approval CHECK (
    status <> 'active' OR approval_status = 'approved'
  )
);

CREATE TABLE IF NOT EXISTS public.organizer_staff (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organizer_id uuid NOT NULL REFERENCES public.organizers (id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES public.profiles (id) ON DELETE CASCADE,
  role public.organizer_staff_role NOT NULL DEFAULT 'manager',
  status public.account_status NOT NULL DEFAULT 'active',
  invited_by uuid REFERENCES public.profiles (id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT organizer_staff_unique UNIQUE (organizer_id, user_id)
);

-- ===== 0003_events.sql =====
-- Phase 1 / 0003: event catalog, public event records and explicit staff assignments.

CREATE TABLE IF NOT EXISTS public.event_categories (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL UNIQUE,
  slug text NOT NULL UNIQUE,
  description text,
  icon text,
  sort_order integer NOT NULL DEFAULT 0,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT event_categories_slug_format CHECK (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  CONSTRAINT event_categories_sort_order_nonnegative CHECK (sort_order >= 0)
);

-- Reference data mirroring the existing frontend categories; no event/business data.
INSERT INTO public.event_categories (name, slug, sort_order)
VALUES
  ('Concerts & Music', 'concerts-music', 1),
  ('Sports', 'sports', 2),
  ('Festivals', 'festivals', 3),
  ('Theatre', 'theatre', 4),
  ('Technology', 'technology', 5),
  ('Workshops', 'workshops', 6),
  ('Business Events', 'business-events', 7),
  ('Other Experiences', 'other-experiences', 8)
ON CONFLICT (slug) DO NOTHING;

CREATE TABLE IF NOT EXISTS public.events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organizer_id uuid NOT NULL REFERENCES public.organizers (id) ON DELETE RESTRICT,
  category_id uuid NOT NULL REFERENCES public.event_categories (id) ON DELETE RESTRICT,
  created_by uuid REFERENCES public.profiles (id) ON DELETE SET NULL,
  title text NOT NULL,
  slug text NOT NULL UNIQUE,
  description text,
  cover_image_url text,
  gallery_image_urls text[] NOT NULL DEFAULT '{}',
  venue_name text,
  venue_address text,
  venue_city text,
  starts_at timestamptz NOT NULL,
  ends_at timestamptz NOT NULL,
  status public.event_status NOT NULL DEFAULT 'draft',
  approval_status public.approval_status NOT NULL DEFAULT 'pending',
  capacity integer,
  published_at timestamptz,
  approved_at timestamptz,
  cancelled_at timestamptz,
  cancellation_reason text,
  completed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT events_slug_format CHECK (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  CONSTRAINT events_title_not_blank CHECK (length(btrim(title)) > 0),
  CONSTRAINT events_time_order CHECK (ends_at > starts_at),
  CONSTRAINT events_capacity_positive CHECK (capacity IS NULL OR capacity > 0),
  CONSTRAINT events_cancelled_has_reason CHECK (
    status <> 'cancelled' OR (cancelled_at IS NOT NULL AND length(btrim(cancellation_reason)) > 0)
  ),
  CONSTRAINT events_published_has_timestamp CHECK (
    status <> 'published' OR published_at IS NOT NULL
  ),
  CONSTRAINT events_approval_timestamp_consistency CHECK (
    (approval_status = 'approved' AND approved_at IS NOT NULL) OR
    (approval_status <> 'approved' AND approved_at IS NULL)
  )
);

COMMENT ON COLUMN public.events.status IS 'Publication lifecycle. Public reads also require approval_status = approved and cancelled_at IS NULL.';
COMMENT ON COLUMN public.events.gallery_image_urls IS 'Storage object paths/URLs. Public only when the event itself is public.';

CREATE TABLE IF NOT EXISTS public.event_lineup_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  event_id uuid NOT NULL REFERENCES public.events (id) ON DELETE CASCADE,
  name text NOT NULL,
  role text,
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT event_lineup_name_not_blank CHECK (length(btrim(name)) > 0),
  CONSTRAINT event_lineup_sort_order_nonnegative CHECK (sort_order >= 0)
);

-- Staff access is event-specific: an assignment here is the only staff path to event data.
CREATE TABLE IF NOT EXISTS public.event_staff (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  event_id uuid NOT NULL REFERENCES public.events (id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES public.profiles (id) ON DELETE CASCADE,
  permission public.event_staff_permission NOT NULL DEFAULT 'view',
  status public.account_status NOT NULL DEFAULT 'active',
  assigned_by uuid REFERENCES public.profiles (id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT event_staff_unique UNIQUE (event_id, user_id)
);

-- ===== 0004_tickets_and_inventory.sql =====
-- Phase 1 / 0004: ticket types and inventory counters.
-- Reservation/checkout execution is intentionally deferred to a later phase.

CREATE TABLE IF NOT EXISTS public.ticket_types (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  event_id uuid NOT NULL REFERENCES public.events (id) ON DELETE CASCADE,
  name text NOT NULL,
  description text,
  price_amount numeric(14,2) NOT NULL,
  currency char(3) NOT NULL DEFAULT 'BDT',
  quantity_total integer NOT NULL,
  max_per_order integer NOT NULL DEFAULT 8,
  sales_start_at timestamptz NOT NULL,
  sales_end_at timestamptz NOT NULL,
  is_active boolean NOT NULL DEFAULT true,
  status public.ticket_type_status NOT NULL DEFAULT 'active',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ticket_types_event_name_key UNIQUE (event_id, name),
  CONSTRAINT ticket_types_name_not_blank CHECK (length(btrim(name)) > 0),
  CONSTRAINT ticket_types_price_nonnegative CHECK (price_amount >= 0),
  CONSTRAINT ticket_types_currency_format CHECK (currency ~ '^[A-Z]{3}$'),
  CONSTRAINT ticket_types_quantity_positive CHECK (quantity_total > 0),
  CONSTRAINT ticket_types_max_per_order_positive CHECK (max_per_order > 0),
  CONSTRAINT ticket_types_max_per_order_within_total CHECK (max_per_order <= quantity_total),
  CONSTRAINT ticket_types_sales_window CHECK (sales_end_at > sales_start_at)
);

COMMENT ON TABLE public.ticket_types IS 'Price/currency and sales-window definition. Monetary values use numeric(14,2); never floating point.';

CREATE TABLE IF NOT EXISTS public.ticket_inventory (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ticket_type_id uuid NOT NULL UNIQUE REFERENCES public.ticket_types (id) ON DELETE CASCADE,
  total_quantity integer NOT NULL,
  reserved_quantity integer NOT NULL DEFAULT 0,
  sold_quantity integer NOT NULL DEFAULT 0,
  available_quantity integer GENERATED ALWAYS AS
    (total_quantity - reserved_quantity - sold_quantity) STORED,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ticket_inventory_total_positive CHECK (total_quantity > 0),
  CONSTRAINT ticket_inventory_reserved_nonnegative CHECK (reserved_quantity >= 0),
  CONSTRAINT ticket_inventory_sold_nonnegative CHECK (sold_quantity >= 0),
  CONSTRAINT ticket_inventory_within_total CHECK (reserved_quantity + sold_quantity <= total_quantity)
);

COMMENT ON COLUMN public.ticket_inventory.available_quantity IS 'Generated invariant: total - reserved - sold. Clients cannot write it.';

-- ===== 0005_orders_and_payments.sql =====
-- Phase 1 / 0005: orders, reservation records and Stripe-ready payment tables.
-- No Stripe calls, webhook handlers or checkout logic are implemented here.

CREATE TABLE IF NOT EXISTS public.orders (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  order_number text NOT NULL UNIQUE DEFAULT (
    'TS-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10))
  ),
  customer_id uuid REFERENCES public.profiles (id) ON DELETE SET NULL,
  event_id uuid NOT NULL REFERENCES public.events (id) ON DELETE RESTRICT,
  status public.order_status NOT NULL DEFAULT 'pending',
  currency char(3) NOT NULL DEFAULT 'BDT',
  subtotal_amount numeric(14,2) NOT NULL,
  discount_amount numeric(14,2) NOT NULL DEFAULT 0,
  fee_amount numeric(14,2) NOT NULL DEFAULT 0,
  total_amount numeric(14,2) NOT NULL,
  buyer_name text NOT NULL,
  buyer_email text NOT NULL,
  buyer_phone text,
  expires_at timestamptz,
  paid_at timestamptz,
  cancelled_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT orders_order_number_format CHECK (order_number ~ '^TS-[A-Z0-9]{6,32}$'),
  CONSTRAINT orders_subtotal_nonnegative CHECK (subtotal_amount >= 0),
  CONSTRAINT orders_discount_nonnegative CHECK (discount_amount >= 0),
  CONSTRAINT orders_fee_nonnegative CHECK (fee_amount >= 0),
  CONSTRAINT orders_total_nonnegative CHECK (total_amount >= 0),
  CONSTRAINT orders_currency_format CHECK (currency ~ '^[A-Z]{3}$'),
  CONSTRAINT orders_buyer_name_not_blank CHECK (length(btrim(buyer_name)) > 0),
  CONSTRAINT orders_buyer_email_format CHECK (
    buyer_email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
  ),
  CONSTRAINT orders_paid_has_timestamp CHECK (status <> 'paid' OR paid_at IS NOT NULL),
  CONSTRAINT orders_cancelled_has_timestamp CHECK (
    status <> 'cancelled' OR cancelled_at IS NOT NULL
  )
);

COMMENT ON COLUMN public.orders.customer_id IS 'Nullable to support guest checkout until auth is wired in a later phase; buyer_email is required.';

CREATE TABLE IF NOT EXISTS public.order_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  order_id uuid NOT NULL REFERENCES public.orders (id) ON DELETE CASCADE,
  ticket_type_id uuid NOT NULL REFERENCES public.ticket_types (id) ON DELETE RESTRICT,
  quantity integer NOT NULL,
  unit_price_amount numeric(14,2) NOT NULL,
  line_total_amount numeric(14,2) NOT NULL,
  currency char(3) NOT NULL DEFAULT 'BDT',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT order_items_order_ticket_type_key UNIQUE (order_id, ticket_type_id),
  CONSTRAINT order_items_quantity_positive CHECK (quantity > 0),
  CONSTRAINT order_items_unit_price_nonnegative CHECK (unit_price_amount >= 0),
  CONSTRAINT order_items_line_total_nonnegative CHECK (line_total_amount >= 0),
  CONSTRAINT order_items_currency_format CHECK (currency ~ '^[A-Z]{3}$'),
  CONSTRAINT order_items_line_total_matches CHECK (
    line_total_amount = unit_price_amount * quantity
  )
);

-- Inventory reservation schema only. Later checkout code must lock inventory rows
-- before mutating these records; Phase 1 does not create reservations.
CREATE TABLE IF NOT EXISTS public.ticket_inventory_reservations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ticket_type_id uuid NOT NULL REFERENCES public.ticket_types (id) ON DELETE RESTRICT,
  order_id uuid REFERENCES public.orders (id) ON DELETE SET NULL,
  quantity integer NOT NULL,
  status public.inventory_reservation_status NOT NULL DEFAULT 'pending',
  idempotency_key text UNIQUE,
  expires_at timestamptz NOT NULL,
  confirmed_at timestamptz,
  released_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ticket_inventory_reservations_quantity_positive CHECK (quantity > 0),
  CONSTRAINT ticket_inventory_reservations_confirmed_has_order CHECK (
    status <> 'confirmed' OR order_id IS NOT NULL
  ),
  CONSTRAINT ticket_inventory_reservations_confirmed_timestamp CHECK (
    status <> 'confirmed' OR confirmed_at IS NOT NULL
  ),
  CONSTRAINT ticket_inventory_reservations_released_timestamp CHECK (
    status NOT IN ('released', 'expired', 'cancelled') OR released_at IS NOT NULL
  )
);

CREATE TABLE IF NOT EXISTS public.payments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  order_id uuid NOT NULL REFERENCES public.orders (id) ON DELETE RESTRICT,
  payment_intent_id text UNIQUE,
  checkout_session_id text UNIQUE,
  transaction_reference text UNIQUE,
  amount numeric(14,2) NOT NULL,
  refunded_amount numeric(14,2) NOT NULL DEFAULT 0,
  currency char(3) NOT NULL DEFAULT 'BDT',
  status public.payment_status NOT NULL DEFAULT 'pending',
  payment_method public.payment_method NOT NULL DEFAULT 'card',
  verified_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT payments_amount_nonnegative CHECK (amount >= 0),
  CONSTRAINT payments_refunded_nonnegative CHECK (refunded_amount >= 0),
  CONSTRAINT payments_refunded_within_amount CHECK (refunded_amount <= amount),
  CONSTRAINT payments_currency_format CHECK (currency ~ '^[A-Z]{3}$'),
  CONSTRAINT payments_succeeded_requires_verification CHECK (
    status <> 'succeeded' OR verified_at IS NOT NULL
  ),
  CONSTRAINT payments_has_provider_reference CHECK (
    payment_intent_id IS NOT NULL OR
    checkout_session_id IS NOT NULL OR
    transaction_reference IS NOT NULL
  )
);

COMMENT ON TABLE public.payments IS 'Provider metadata only. Card numbers, CVCs and raw credentials must never be stored here.';

CREATE TABLE IF NOT EXISTS public.payment_webhook_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  provider text NOT NULL DEFAULT 'stripe',
  event_id text NOT NULL UNIQUE,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}'::jsonb,
  signature_verified boolean NOT NULL DEFAULT false,
  processed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT payment_webhook_events_provider_not_blank CHECK (length(btrim(provider)) > 0),
  CONSTRAINT payment_webhook_events_type_not_blank CHECK (length(btrim(event_type)) > 0)
);

COMMENT ON TABLE public.payment_webhook_events IS 'Idempotency ledger for provider webhooks. Payloads must be sanitized before storage; no raw card data.';

-- ===== 0006_tickets_and_checkins.sql =====
-- Phase 1 / 0006: issued tickets, QR verification token storage and one-time check-in ledger.
-- QR generation and verification endpoints are deferred to a later phase.

CREATE TABLE IF NOT EXISTS public.tickets (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ticket_number text NOT NULL UNIQUE DEFAULT (
    'TSK-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 12))
  ),
  order_id uuid NOT NULL REFERENCES public.orders (id) ON DELETE RESTRICT,
  order_item_id uuid NOT NULL REFERENCES public.order_items (id) ON DELETE RESTRICT,
  customer_id uuid REFERENCES public.profiles (id) ON DELETE SET NULL,
  event_id uuid NOT NULL REFERENCES public.events (id) ON DELETE RESTRICT,
  ticket_type_id uuid NOT NULL REFERENCES public.ticket_types (id) ON DELETE RESTRICT,
  qr_token_hash text NOT NULL UNIQUE,
  status public.ticket_status NOT NULL DEFAULT 'valid',
  checkin_status public.checkin_status NOT NULL DEFAULT 'not_checked_in',
  issued_at timestamptz NOT NULL DEFAULT now(),
  checked_in_at timestamptz,
  token_issued_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT tickets_hash_is_sha256 CHECK (qr_token_hash ~ '^[a-f0-9]{64}$'),
  CONSTRAINT tickets_checked_in_timestamp CHECK (
    checkin_status <> 'checked_in' OR checked_in_at IS NOT NULL
  ),
  CONSTRAINT tickets_usable_status CHECK (
    status NOT IN ('cancelled', 'refunded', 'expired') OR checkin_status <> 'checked_in'
  )
);

COMMENT ON COLUMN public.tickets.qr_token_hash IS 'SHA-256 hash of a high-entropy token. The raw QR token is never stored in the database.';

CREATE TABLE IF NOT EXISTS public.ticket_checkins (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ticket_id uuid NOT NULL REFERENCES public.tickets (id) ON DELETE CASCADE,
  event_id uuid NOT NULL REFERENCES public.events (id) ON DELETE RESTRICT,
  scanned_by uuid REFERENCES public.profiles (id) ON DELETE SET NULL,
  result public.checkin_result NOT NULL,
  denied_reason text,
  device_info text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ticket_checkins_denied_has_reason CHECK (
    result <> 'denied' OR (denied_reason IS NOT NULL AND length(btrim(denied_reason)) > 0)
  )
);

COMMENT ON TABLE public.ticket_checkins IS 'Append-only-style verification ledger. A partial unique index enforces at most one successful check-in per ticket.';

-- ===== 0007_finance.sql =====
-- Phase 1 / 0007: refunds, commissions and payout records.
-- All money values are numeric(14,2) with explicit currency codes.

CREATE TABLE IF NOT EXISTS public.refunds (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  payment_id uuid NOT NULL REFERENCES public.payments (id) ON DELETE RESTRICT,
  order_id uuid NOT NULL REFERENCES public.orders (id) ON DELETE RESTRICT,
  stripe_refund_id text UNIQUE,
  amount numeric(14,2) NOT NULL,
  currency char(3) NOT NULL DEFAULT 'BDT',
  status public.refund_status NOT NULL DEFAULT 'pending',
  reason text,
  processed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT refunds_amount_positive CHECK (amount > 0),
  CONSTRAINT refunds_currency_format CHECK (currency ~ '^[A-Z]{3}$'),
  CONSTRAINT refunds_processed_timestamp CHECK (
    status <> 'succeeded' OR processed_at IS NOT NULL
  )
);

CREATE TABLE IF NOT EXISTS public.organizer_payouts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organizer_id uuid NOT NULL REFERENCES public.organizers (id) ON DELETE RESTRICT,
  payout_reference text NOT NULL UNIQUE DEFAULT (
    'PO-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 12))
  ),
  amount numeric(14,2) NOT NULL,
  currency char(3) NOT NULL DEFAULT 'BDT',
  status public.payout_status NOT NULL DEFAULT 'pending',
  requested_at timestamptz NOT NULL DEFAULT now(),
  paid_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT organizer_payouts_amount_positive CHECK (amount > 0),
  CONSTRAINT organizer_payouts_currency_format CHECK (currency ~ '^[A-Z]{3}$'),
  CONSTRAINT organizer_payouts_paid_timestamp CHECK (
    status <> 'paid' OR paid_at IS NOT NULL
  ),
  CONSTRAINT organizer_payouts_reference_format CHECK (payout_reference ~ '^PO-[A-Z0-9]{6,32}$')
);

CREATE TABLE IF NOT EXISTS public.organizer_commissions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organizer_id uuid NOT NULL REFERENCES public.organizers (id) ON DELETE RESTRICT,
  event_id uuid REFERENCES public.events (id) ON DELETE RESTRICT,
  order_id uuid REFERENCES public.orders (id) ON DELETE RESTRICT,
  payout_id uuid REFERENCES public.organizer_payouts (id) ON DELETE SET NULL,
  commission_rate numeric(5,4) NOT NULL,
  gross_amount numeric(14,2) NOT NULL,
  commission_amount numeric(14,2) NOT NULL,
  net_amount numeric(14,2) NOT NULL,
  currency char(3) NOT NULL DEFAULT 'BDT',
  status public.commission_status NOT NULL DEFAULT 'pending',
  period_start timestamptz,
  period_end timestamptz,
  calculated_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT organizer_commissions_rate_range CHECK (
    commission_rate >= 0 AND commission_rate <= 1
  ),
  CONSTRAINT organizer_commissions_gross_nonnegative CHECK (gross_amount >= 0),
  CONSTRAINT organizer_commissions_commission_nonnegative CHECK (commission_amount >= 0),
  CONSTRAINT organizer_commissions_net_nonnegative CHECK (net_amount >= 0),
  CONSTRAINT organizer_commissions_amount_math CHECK (
    gross_amount = commission_amount + net_amount
  ),
  CONSTRAINT organizer_commissions_currency_format CHECK (currency ~ '^[A-Z]{3}$'),
  CONSTRAINT organizer_commissions_period_order CHECK (
    period_start IS NULL OR period_end IS NULL OR period_end > period_start
  )
);

-- ===== 0008_engagement_and_admin.sql =====
-- Phase 1 / 0008: notifications, reviews, platform settings and immutable audit log.

CREATE TABLE IF NOT EXISTS public.notifications (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES public.profiles (id) ON DELETE CASCADE,
  type public.notification_type NOT NULL,
  title text NOT NULL,
  body text,
  data jsonb NOT NULL DEFAULT '{}'::jsonb,
  read_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT notifications_title_not_blank CHECK (length(btrim(title)) > 0)
);

CREATE TABLE IF NOT EXISTS public.reviews (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  event_id uuid NOT NULL REFERENCES public.events (id) ON DELETE CASCADE,
  customer_id uuid NOT NULL REFERENCES public.profiles (id) ON DELETE CASCADE,
  rating smallint NOT NULL,
  title text,
  comment text,
  status public.review_status NOT NULL DEFAULT 'pending',
  moderated_by uuid REFERENCES public.profiles (id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT reviews_event_customer_key UNIQUE (event_id, customer_id),
  CONSTRAINT reviews_rating_range CHECK (rating >= 1 AND rating <= 5),
  CONSTRAINT reviews_comment_present CHECK (
    comment IS NOT NULL OR title IS NOT NULL
  )
);

CREATE TABLE IF NOT EXISTS public.platform_settings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  key text NOT NULL UNIQUE,
  value jsonb NOT NULL,
  description text,
  is_public boolean NOT NULL DEFAULT false,
  updated_by uuid REFERENCES public.profiles (id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT platform_settings_key_format CHECK (
    key ~ '^[a-z][a-z0-9_]*(\.[a-z0-9_]+)*$'
  )
);

COMMENT ON TABLE public.platform_settings IS 'is_public = true is the only flag that exposes setting values to anonymous clients.';

CREATE TABLE IF NOT EXISTS public.audit_logs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  actor_id uuid REFERENCES public.profiles (id) ON DELETE SET NULL,
  actor_role public.app_role,
  action text NOT NULL,
  entity_type text NOT NULL,
  entity_id uuid,
  changes jsonb NOT NULL DEFAULT '{}'::jsonb,
  ip_address inet,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT audit_logs_action_not_blank CHECK (length(btrim(action)) > 0),
  CONSTRAINT audit_logs_entity_type_not_blank CHECK (length(btrim(entity_type)) > 0)
);

COMMENT ON TABLE public.audit_logs IS 'Append-only audit trail. No UPDATE/DELETE policy is granted; only service-role/backend writes.';

-- ===== 0009_indexes.sql =====
-- Phase 1 / 0009: query and foreign-key indexes.
-- All indexes are CREATE IF NOT EXISTS; no data is modified.

-- Identity / permissions
CREATE INDEX IF NOT EXISTS profiles_email_lower_idx ON public.profiles (lower(email)) WHERE email IS NOT NULL;
CREATE INDEX IF NOT EXISTS user_roles_user_idx ON public.user_roles (user_id);
CREATE INDEX IF NOT EXISTS user_roles_role_idx ON public.user_roles (role_id);
CREATE INDEX IF NOT EXISTS organizer_staff_user_idx ON public.organizer_staff (user_id) WHERE status = 'active';
CREATE INDEX IF NOT EXISTS organizer_staff_organizer_idx ON public.organizer_staff (organizer_id) WHERE status = 'active';
CREATE INDEX IF NOT EXISTS organizers_owner_idx ON public.organizers (owner_id);
CREATE INDEX IF NOT EXISTS organizers_public_idx ON public.organizers (status, approval_status) WHERE status = 'active' AND approval_status = 'approved';

-- Events
CREATE INDEX IF NOT EXISTS events_organizer_idx ON public.events (organizer_id);
CREATE INDEX IF NOT EXISTS events_category_idx ON public.events (category_id);
CREATE INDEX IF NOT EXISTS events_public_idx ON public.events (starts_at, id)
  WHERE status = 'published' AND approval_status = 'approved' AND cancelled_at IS NULL;
CREATE INDEX IF NOT EXISTS events_status_idx ON public.events (status, approval_status, starts_at);
CREATE INDEX IF NOT EXISTS event_lineup_items_event_idx ON public.event_lineup_items (event_id, sort_order);
CREATE INDEX IF NOT EXISTS event_staff_user_idx ON public.event_staff (user_id) WHERE status = 'active';
CREATE INDEX IF NOT EXISTS event_staff_event_idx ON public.event_staff (event_id) WHERE status = 'active';

-- Tickets / inventory
CREATE INDEX IF NOT EXISTS ticket_types_event_idx ON public.ticket_types (event_id, status);
CREATE INDEX IF NOT EXISTS ticket_types_sales_window_idx ON public.ticket_types (sales_start_at, sales_end_at) WHERE is_active;
CREATE INDEX IF NOT EXISTS ticket_inventory_ticket_type_idx ON public.ticket_inventory (ticket_type_id);
CREATE INDEX IF NOT EXISTS ticket_reservations_status_expiry_idx
  ON public.ticket_inventory_reservations (status, expires_at) WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS ticket_reservations_order_idx ON public.ticket_inventory_reservations (order_id);

-- Orders / payments
CREATE INDEX IF NOT EXISTS orders_customer_idx ON public.orders (customer_id, created_at DESC);
CREATE INDEX IF NOT EXISTS orders_event_idx ON public.orders (event_id, created_at DESC);
CREATE INDEX IF NOT EXISTS orders_status_idx ON public.orders (status, created_at DESC);
CREATE INDEX IF NOT EXISTS orders_buyer_email_idx ON public.orders (lower(buyer_email));
CREATE INDEX IF NOT EXISTS order_items_order_idx ON public.order_items (order_id);
CREATE INDEX IF NOT EXISTS order_items_ticket_type_idx ON public.order_items (ticket_type_id);
CREATE INDEX IF NOT EXISTS payments_order_idx ON public.payments (order_id, created_at DESC);
CREATE INDEX IF NOT EXISTS payments_status_idx ON public.payments (status, verified_at);
CREATE INDEX IF NOT EXISTS payment_webhook_events_processed_idx
  ON public.payment_webhook_events (processed_at) WHERE processed_at IS NULL;

-- Issued tickets / verification
CREATE INDEX IF NOT EXISTS tickets_order_idx ON public.tickets (order_id);
CREATE INDEX IF NOT EXISTS tickets_order_item_idx ON public.tickets (order_item_id);
CREATE INDEX IF NOT EXISTS tickets_customer_idx ON public.tickets (customer_id, created_at DESC);
CREATE INDEX IF NOT EXISTS tickets_event_idx ON public.tickets (event_id, status);
CREATE INDEX IF NOT EXISTS tickets_ticket_type_idx ON public.tickets (ticket_type_id);
CREATE INDEX IF NOT EXISTS ticket_checkins_ticket_idx ON public.ticket_checkins (ticket_id, created_at DESC);
CREATE INDEX IF NOT EXISTS ticket_checkins_event_idx ON public.ticket_checkins (event_id, created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS ticket_checkins_one_success_idx
  ON public.ticket_checkins (ticket_id) WHERE result = 'success';

-- Finance
CREATE INDEX IF NOT EXISTS refunds_payment_idx ON public.refunds (payment_id);
CREATE INDEX IF NOT EXISTS refunds_order_idx ON public.refunds (order_id);
CREATE INDEX IF NOT EXISTS refunds_status_idx ON public.refunds (status, processed_at);
CREATE INDEX IF NOT EXISTS organizer_commissions_organizer_idx ON public.organizer_commissions (organizer_id, created_at DESC);
CREATE INDEX IF NOT EXISTS organizer_commissions_event_idx ON public.organizer_commissions (event_id);
CREATE INDEX IF NOT EXISTS organizer_commissions_order_idx ON public.organizer_commissions (order_id) WHERE order_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS organizer_commissions_payout_idx ON public.organizer_commissions (payout_id) WHERE payout_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS organizer_commissions_one_per_order_idx
  ON public.organizer_commissions (organizer_id, order_id) WHERE order_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS organizer_payouts_organizer_idx ON public.organizer_payouts (organizer_id, created_at DESC);
CREATE INDEX IF NOT EXISTS organizer_payouts_status_idx ON public.organizer_payouts (status, requested_at);

-- Engagement / audit
CREATE INDEX IF NOT EXISTS notifications_user_unread_idx ON public.notifications (user_id, created_at DESC) WHERE read_at IS NULL;
CREATE INDEX IF NOT EXISTS reviews_event_status_idx ON public.reviews (event_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS reviews_customer_idx ON public.reviews (customer_id);
CREATE INDEX IF NOT EXISTS audit_logs_actor_idx ON public.audit_logs (actor_id, created_at DESC);
CREATE INDEX IF NOT EXISTS audit_logs_entity_idx ON public.audit_logs (entity_type, entity_id, created_at DESC);
CREATE INDEX IF NOT EXISTS audit_logs_created_idx ON public.audit_logs (created_at DESC);

-- ===== 0010_functions_and_triggers.sql =====
-- Phase 1 / 0010: security helpers, moderation guards and consistency triggers.
-- Every SECURITY DEFINER function pins search_path to avoid search-path injection.

CREATE OR REPLACE FUNCTION public.set_updated_at()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.is_service_role()
RETURNS boolean
LANGUAGE sql
STABLE
SET search_path = public, pg_temp
AS $$
  SELECT coalesce(auth.jwt() ->> 'role', current_setting('request.jwt.claim.role', true), '') = 'service_role';
$$;

CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT public.is_service_role() OR EXISTS (
    SELECT 1
    FROM public.user_roles ur
    JOIN public.roles r ON r.id = ur.role_id
    WHERE ur.user_id = auth.uid() AND r.name = 'admin'
  );
$$;

CREATE OR REPLACE FUNCTION public.has_role(p_role public.app_role)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT public.is_service_role() OR EXISTS (
    SELECT 1
    FROM public.user_roles ur
    JOIN public.roles r ON r.id = ur.role_id
    WHERE ur.user_id = auth.uid() AND r.name = p_role
  );
$$;

CREATE OR REPLACE FUNCTION public.owns_organizer(p_organizer_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.organizers o
    WHERE o.id = p_organizer_id AND o.owner_id = auth.uid()
  );
$$;

CREATE OR REPLACE FUNCTION public.owns_active_organizer(p_organizer_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT public.has_role('organizer') AND EXISTS (
    SELECT 1 FROM public.organizers o
    WHERE o.id = p_organizer_id
      AND o.owner_id = auth.uid()
      AND o.status = 'active'
      AND o.approval_status = 'approved'
  );
$$;

CREATE OR REPLACE FUNCTION public.can_manage_organizer(p_organizer_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT public.is_admin()
    OR (public.has_role('organizer') AND public.owns_organizer(p_organizer_id));
$$;

CREATE OR REPLACE FUNCTION public.can_access_event(p_event_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT public.is_admin()
    OR (
      public.has_role('organizer')
      AND public.owns_organizer((SELECT e.organizer_id FROM public.events e WHERE e.id = p_event_id))
    )
    OR EXISTS (
      SELECT 1
      FROM public.event_staff es
      WHERE es.event_id = p_event_id
        AND es.user_id = auth.uid()
        AND es.status = 'active'
    );
$$;

CREATE OR REPLACE FUNCTION public.can_manage_event(p_event_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT public.is_admin()
    OR (
      public.has_role('organizer')
      AND public.owns_organizer((SELECT e.organizer_id FROM public.events e WHERE e.id = p_event_id))
    );
$$;

CREATE OR REPLACE FUNCTION public.can_checkin_event(p_event_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT public.is_admin()
    OR (
      public.has_role('organizer')
      AND public.owns_organizer((SELECT e.organizer_id FROM public.events e WHERE e.id = p_event_id))
    )
    OR EXISTS (
      SELECT 1
      FROM public.event_staff es
      WHERE es.event_id = p_event_id
        AND es.user_id = auth.uid()
        AND es.status = 'active'
        AND es.permission IN ('checkin', 'manage_orders')
    );
$$;

CREATE OR REPLACE FUNCTION public.is_event_public(p_event_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.events e
    WHERE e.id = p_event_id
      AND e.status = 'published'
      AND e.approval_status = 'approved'
      AND e.cancelled_at IS NULL
  );
$$;

CREATE OR REPLACE FUNCTION public.owns_order(p_order_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.orders o
    WHERE o.id = p_order_id
      AND (
        o.customer_id = auth.uid()
        OR (o.buyer_email IS NOT NULL AND lower(o.buyer_email) = lower(coalesce(auth.jwt() ->> 'email', '')))
      )
  );
$$;

CREATE OR REPLACE FUNCTION public.can_access_order(p_order_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT public.is_admin()
    OR public.owns_order(p_order_id)
    OR public.can_access_event((SELECT o.event_id FROM public.orders o WHERE o.id = p_order_id));
$$;

CREATE OR REPLACE FUNCTION public.can_view_ticket(p_ticket_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT public.is_admin()
    OR EXISTS (
      SELECT 1 FROM public.tickets t
      WHERE t.id = p_ticket_id
        AND (
          t.customer_id = auth.uid()
          OR public.owns_order(t.order_id)
          OR public.can_access_event(t.event_id)
        )
    );
$$;

CREATE OR REPLACE FUNCTION public.can_access_reservation(p_reservation_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT public.is_admin()
    OR EXISTS (
      SELECT 1
      FROM public.ticket_inventory_reservations r
      WHERE r.id = p_reservation_id
        AND (
          public.owns_order(r.order_id)
          OR public.can_access_event((SELECT tt.event_id FROM public.ticket_types tt WHERE tt.id = r.ticket_type_id))
        )
    );
$$;

CREATE OR REPLACE FUNCTION public.storage_path_uuid(p_name text)
RETURNS uuid
LANGUAGE sql
IMMUTABLE
SET search_path = public, pg_temp
AS $$
  SELECT CASE
    WHEN split_part(p_name, '/', 1) ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    THEN split_part(p_name, '/', 1)::uuid
    ELSE NULL
  END;
$$;

CREATE OR REPLACE FUNCTION public.storage_path_owned_by_user(p_name text)
RETURNS boolean
LANGUAGE sql
STABLE
SET search_path = public, pg_temp
AS $$
  SELECT split_part(p_name, '/', 1) = auth.uid()::text;
$$;

-- Role changes go through these two functions only. Direct client DML is denied by RLS.
CREATE OR REPLACE FUNCTION public.assign_user_role(p_user_id uuid, p_role public.app_role)
RETURNS public.user_roles
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_role_id uuid;
  v_result public.user_roles;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Only administrators can assign roles';
  END IF;

  IF p_user_id = auth.uid() AND p_role IN ('admin', 'organizer') THEN
    RAISE EXCEPTION 'Self-assignment of admin/organizer roles is not allowed';
  END IF;

  SELECT id INTO v_role_id FROM public.roles WHERE name = p_role;
  IF v_role_id IS NULL THEN
    RAISE EXCEPTION 'Unknown role: %', p_role;
  END IF;

  INSERT INTO public.user_roles (user_id, role_id, assigned_by)
  VALUES (p_user_id, v_role_id, auth.uid())
  ON CONFLICT (user_id, role_id) DO NOTHING;

  SELECT * INTO v_result
  FROM public.user_roles
  WHERE user_id = p_user_id AND role_id = v_role_id;

  RETURN v_result;
END;
$$;

CREATE OR REPLACE FUNCTION public.remove_user_role(p_user_id uuid, p_role public.app_role)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_deleted integer;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Only administrators can remove roles';
  END IF;

  IF p_user_id = auth.uid() AND p_role = 'admin' THEN
    RAISE EXCEPTION 'Administrators cannot remove their own admin role';
  END IF;

  DELETE FROM public.user_roles ur
  USING public.roles r
  WHERE ur.role_id = r.id
    AND r.name = p_role
    AND ur.user_id = p_user_id;

  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted > 0;
END;
$$;

REVOKE ALL ON FUNCTION public.assign_user_role(uuid, public.app_role) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.remove_user_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.assign_user_role(uuid, public.app_role) TO authenticated;
GRANT EXECUTE ON FUNCTION public.remove_user_role(uuid, public.app_role) TO authenticated;

CREATE OR REPLACE FUNCTION public.prevent_user_role_self_escalation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF TG_OP IN ('INSERT', 'UPDATE')
     AND NEW.user_id = auth.uid()
     AND EXISTS (
       SELECT 1 FROM public.roles r
       WHERE r.id = NEW.role_id AND r.name IN ('admin', 'organizer')
     )
     AND NOT public.is_service_role() THEN
    RAISE EXCEPTION 'Self-assignment of admin/organizer roles is not allowed';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.enforce_profile_update()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF NOT public.is_admin()
     AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.id IS DISTINCT FROM OLD.id) THEN
    RAISE EXCEPTION 'Profile status and identity cannot be changed by the user';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.enforce_organizer_moderation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF NOT public.is_admin()
     AND (
       NEW.status IS DISTINCT FROM OLD.status
       OR NEW.approval_status IS DISTINCT FROM OLD.approval_status
       OR NEW.approved_at IS DISTINCT FROM OLD.approved_at
       OR NEW.owner_id IS DISTINCT FROM OLD.owner_id
     ) THEN
    RAISE EXCEPTION 'Organizer status, approval and ownership can only be changed by an administrator';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.enforce_event_moderation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF public.is_admin() THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status NOT IN ('draft', 'pending') THEN
      RAISE EXCEPTION 'New events must start as draft or pending';
    END IF;
    IF NEW.approval_status <> 'pending' THEN
      RAISE EXCEPTION 'Event approval can only be set by an administrator';
    END IF;
    NEW.approved_at := NULL;
    NEW.published_at := NULL;
    NEW.cancelled_at := NULL;
    NEW.completed_at := NULL;
    RETURN NEW;
  END IF;

  IF NEW.approval_status IS DISTINCT FROM OLD.approval_status
     OR NEW.approved_at IS DISTINCT FROM OLD.approved_at
     OR NEW.published_at IS DISTINCT FROM OLD.published_at THEN
    RAISE EXCEPTION 'Event approval/publication fields can only be changed by an administrator';
  END IF;

  IF OLD.status IN ('rejected', 'cancelled', 'completed')
     AND NEW.status IS DISTINCT FROM OLD.status THEN
    RAISE EXCEPTION 'Only administrators can reopen rejected, cancelled or completed events';
  END IF;

  IF NEW.status = 'published' AND OLD.approval_status <> 'approved' THEN
    RAISE EXCEPTION 'An event must be approved before it can be published';
  END IF;

  IF NEW.status = 'cancelled' THEN
    NEW.cancelled_at := coalesce(NEW.cancelled_at, now());
  END IF;

  IF NEW.status = 'completed' THEN
    NEW.completed_at := coalesce(NEW.completed_at, now());
  END IF;

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.enforce_review_moderation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF NEW.status = 'pending' OR public.is_admin() OR public.can_manage_event(NEW.event_id) THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'Only administrators or event owners can moderate reviews';
END;
$$;

CREATE OR REPLACE FUNCTION public.sync_ticket_inventory_on_ticket_type()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  INSERT INTO public.ticket_inventory (ticket_type_id, total_quantity)
  VALUES (NEW.id, NEW.quantity_total)
  ON CONFLICT (ticket_type_id) DO UPDATE
    SET total_quantity = EXCLUDED.total_quantity,
        updated_at = now();
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.sync_ticket_inventory_on_reservation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_old_reserved integer;
  v_old_sold integer;
  v_new_reserved integer;
  v_new_sold integer;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.ticket_type_id IS DISTINCT FROM OLD.ticket_type_id THEN
    RAISE EXCEPTION 'A reservation cannot be moved to a different ticket type';
  END IF;

  v_old_reserved := CASE
    WHEN TG_OP IN ('UPDATE', 'DELETE') AND OLD.status = 'pending' THEN OLD.quantity ELSE 0 END;
  v_old_sold := CASE
    WHEN TG_OP IN ('UPDATE', 'DELETE') AND OLD.status = 'confirmed' THEN OLD.quantity ELSE 0 END;
  v_new_reserved := CASE
    WHEN TG_OP IN ('INSERT', 'UPDATE') AND NEW.status = 'pending' THEN NEW.quantity ELSE 0 END;
  v_new_sold := CASE
    WHEN TG_OP IN ('INSERT', 'UPDATE') AND NEW.status = 'confirmed' THEN NEW.quantity ELSE 0 END;

  UPDATE public.ticket_inventory ti
  SET reserved_quantity = ti.reserved_quantity - v_old_reserved + v_new_reserved,
      sold_quantity = ti.sold_quantity - v_old_sold + v_new_sold,
      updated_at = now()
  WHERE ti.ticket_type_id = coalesce(NEW.ticket_type_id, OLD.ticket_type_id);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Inventory row missing for reserved ticket type';
  END IF;

  RETURN coalesce(NEW, OLD);
END;
$$;

CREATE OR REPLACE FUNCTION public.enforce_refund_amount()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_payment_amount numeric(14,2);
  v_payment_currency char(3);
  v_already_refunded numeric(14,2);
BEGIN
  SELECT p.amount, p.currency INTO v_payment_amount, v_payment_currency
  FROM public.payments p WHERE p.id = NEW.payment_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payment not found';
  END IF;

  IF NEW.currency IS DISTINCT FROM v_payment_currency THEN
    RAISE EXCEPTION 'Refund currency must match payment currency';
  END IF;

  SELECT coalesce(sum(r.amount), 0) INTO v_already_refunded
  FROM public.refunds r
  WHERE r.payment_id = NEW.payment_id
    AND r.status = 'succeeded'
    AND r.id IS DISTINCT FROM NEW.id;

  IF NEW.amount > v_payment_amount - v_already_refunded THEN
    RAISE EXCEPTION 'Refund exceeds the remaining payment amount';
  END IF;

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.sync_payment_refunded_amount()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_payment_id uuid;
BEGIN
  v_payment_id := coalesce(NEW.payment_id, OLD.payment_id);
  UPDATE public.payments p
  SET refunded_amount = coalesce((
    SELECT sum(r.amount) FROM public.refunds r
    WHERE r.payment_id = v_payment_id AND r.status = 'succeeded'
  ), 0),
      updated_at = now()
  WHERE p.id = v_payment_id;
  RETURN coalesce(NEW, OLD);
END;
$$;

CREATE OR REPLACE FUNCTION public.enforce_ticket_checkin_event()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_ticket public.tickets;
BEGIN
  SELECT * INTO v_ticket FROM public.tickets t WHERE t.id = NEW.ticket_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket not found';
  END IF;

  IF NEW.event_id IS DISTINCT FROM v_ticket.event_id THEN
    RAISE EXCEPTION 'Check-in event must match the ticket event';
  END IF;

  IF NEW.result = 'success' AND v_ticket.status NOT IN ('valid', 'used') THEN
    RAISE EXCEPTION 'Only valid or already-used tickets can be checked in';
  END IF;

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.apply_ticket_checkin_result()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF NEW.result = 'success' THEN
    UPDATE public.tickets
    SET checkin_status = 'checked_in',
        checked_in_at = NEW.created_at,
        status = CASE WHEN status = 'valid' THEN 'used' ELSE status END,
        updated_at = now()
    WHERE id = NEW.ticket_id;
  ELSIF NEW.result = 'reversed' THEN
    UPDATE public.tickets
    SET checkin_status = 'not_checked_in',
        checked_in_at = NULL,
        status = CASE WHEN status = 'used' THEN 'valid' ELSE status END,
        updated_at = now()
    WHERE id = NEW.ticket_id;
  END IF;
  RETURN NEW;
END;
$$;

