-- ===== 0011_row_level_security.sql =====
-- Phase 1 / 0011: row level security.
-- Default deny: only the policies below grant access. Service role bypasses RLS by design
-- and must remain server-side only.

ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.roles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.organizers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.organizer_staff ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.event_categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.event_lineup_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.event_staff ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ticket_types ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ticket_inventory ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ticket_inventory_reservations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.order_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payment_webhook_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.tickets ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ticket_checkins ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.refunds ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.organizer_commissions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.organizer_payouts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.platform_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;

-- profiles: private by default; users may edit their own non-status fields.
DROP POLICY IF EXISTS profiles_select ON public.profiles;
CREATE POLICY profiles_select ON public.profiles
  FOR SELECT TO authenticated USING (id = auth.uid() OR public.is_admin());
DROP POLICY IF EXISTS profiles_update ON public.profiles;
CREATE POLICY profiles_update ON public.profiles
  FOR UPDATE TO authenticated
  USING (id = auth.uid() OR public.is_admin())
  WITH CHECK (id = auth.uid() OR public.is_admin());

-- roles: reference data readable by signed-in users, writable only by service role.
DROP POLICY IF EXISTS roles_select ON public.roles;
CREATE POLICY roles_select ON public.roles FOR SELECT TO authenticated USING (true);

-- user_roles: readable by the user/admin, writable only through security-definer functions.
DROP POLICY IF EXISTS user_roles_select ON public.user_roles;
CREATE POLICY user_roles_select ON public.user_roles
  FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.is_admin());

-- organizers: public directory only for active approved organizers.
DROP POLICY IF EXISTS organizers_public_select ON public.organizers;
CREATE POLICY organizers_public_select ON public.organizers
  FOR SELECT TO public USING (status = 'active' AND approval_status = 'approved');
DROP POLICY IF EXISTS organizers_member_select ON public.organizers;
CREATE POLICY organizers_member_select ON public.organizers
  FOR SELECT TO authenticated USING (
    public.is_admin()
    OR public.owns_organizer(id)
    OR EXISTS (
      SELECT 1 FROM public.organizer_staff os
      WHERE os.organizer_id = organizers.id
        AND os.user_id = auth.uid()
        AND os.status = 'active'
    )
  );
DROP POLICY IF EXISTS organizers_insert ON public.organizers;
CREATE POLICY organizers_insert ON public.organizers
  FOR INSERT TO authenticated WITH CHECK (
    public.is_admin()
    OR (
      public.has_role('organizer')
      AND owner_id = auth.uid()
      AND status = 'pending'
      AND approval_status = 'pending'
      AND approved_at IS NULL
    )
  );
DROP POLICY IF EXISTS organizers_update ON public.organizers;
CREATE POLICY organizers_update ON public.organizers
  FOR UPDATE TO authenticated
  USING (public.can_manage_organizer(id))
  WITH CHECK (public.can_manage_organizer(id));
DROP POLICY IF EXISTS organizers_delete ON public.organizers;
CREATE POLICY organizers_delete ON public.organizers
  FOR DELETE TO authenticated USING (public.is_admin());

-- organizer_staff: members see their own assignment; owners/admins manage assignments.
DROP POLICY IF EXISTS organizer_staff_select ON public.organizer_staff;
CREATE POLICY organizer_staff_select ON public.organizer_staff
  FOR SELECT TO authenticated USING (
    public.is_admin() OR public.owns_organizer(organizer_id) OR user_id = auth.uid()
  );
DROP POLICY IF EXISTS organizer_staff_insert ON public.organizer_staff;
CREATE POLICY organizer_staff_insert ON public.organizer_staff
  FOR INSERT TO authenticated WITH CHECK (public.can_manage_organizer(organizer_id));
DROP POLICY IF EXISTS organizer_staff_update ON public.organizer_staff;
CREATE POLICY organizer_staff_update ON public.organizer_staff
  FOR UPDATE TO authenticated
  USING (public.can_manage_organizer(organizer_id))
  WITH CHECK (public.can_manage_organizer(organizer_id));
DROP POLICY IF EXISTS organizer_staff_delete ON public.organizer_staff;
CREATE POLICY organizer_staff_delete ON public.organizer_staff
  FOR DELETE TO authenticated USING (public.can_manage_organizer(organizer_id));

-- event_categories: active categories are public; inactive ones are admin-only.
DROP POLICY IF EXISTS event_categories_select ON public.event_categories;
CREATE POLICY event_categories_select ON public.event_categories
  FOR SELECT TO public USING (is_active OR public.is_admin());
DROP POLICY IF EXISTS event_categories_write ON public.event_categories;
CREATE POLICY event_categories_write ON public.event_categories
  FOR ALL TO authenticated
  USING (public.is_admin()) WITH CHECK (public.is_admin());

-- events: the core public rule is status=published AND approval_status=approved.
DROP POLICY IF EXISTS events_public_select ON public.events;
CREATE POLICY events_public_select ON public.events
  FOR SELECT TO public USING (public.is_event_public(id));
DROP POLICY IF EXISTS events_member_select ON public.events;
CREATE POLICY events_member_select ON public.events
  FOR SELECT TO authenticated USING (public.can_access_event(id));
DROP POLICY IF EXISTS events_insert ON public.events;
CREATE POLICY events_insert ON public.events
  FOR INSERT TO authenticated WITH CHECK (
    public.is_admin()
    OR (
      public.owns_active_organizer(organizer_id)
      AND status IN ('draft', 'pending')
      AND approval_status = 'pending'
      AND approved_at IS NULL
      AND published_at IS NULL
      AND cancelled_at IS NULL
    )
  );
DROP POLICY IF EXISTS events_update ON public.events;
CREATE POLICY events_update ON public.events
  FOR UPDATE TO authenticated
  USING (public.can_manage_event(id)) WITH CHECK (public.can_manage_event(id));
DROP POLICY IF EXISTS events_delete ON public.events;
CREATE POLICY events_delete ON public.events FOR DELETE TO authenticated USING (public.is_admin());

-- event_lineup_items: follows the parent event's visibility/access.
DROP POLICY IF EXISTS event_lineup_public_select ON public.event_lineup_items;
CREATE POLICY event_lineup_public_select ON public.event_lineup_items
  FOR SELECT TO public USING (public.is_event_public(event_id));
DROP POLICY IF EXISTS event_lineup_member_select ON public.event_lineup_items;
CREATE POLICY event_lineup_member_select ON public.event_lineup_items
  FOR SELECT TO authenticated USING (public.can_access_event(event_id));
DROP POLICY IF EXISTS event_lineup_write ON public.event_lineup_items;
CREATE POLICY event_lineup_write ON public.event_lineup_items
  FOR ALL TO authenticated
  USING (public.can_manage_event(event_id)) WITH CHECK (public.can_manage_event(event_id));

-- event_staff: explicit per-event assignments only.
DROP POLICY IF EXISTS event_staff_select ON public.event_staff;
CREATE POLICY event_staff_select ON public.event_staff
  FOR SELECT TO authenticated USING (
    user_id = auth.uid()
    OR public.is_admin()
    OR public.owns_organizer((SELECT e.organizer_id FROM public.events e WHERE e.id = event_staff.event_id))
  );
DROP POLICY IF EXISTS event_staff_write ON public.event_staff;
CREATE POLICY event_staff_write ON public.event_staff
  FOR ALL TO authenticated
  USING (public.can_manage_event(event_id)) WITH CHECK (public.can_manage_event(event_id));

-- ticket_types and inventory: public buyers see active sale data for public events only.
DROP POLICY IF EXISTS ticket_types_public_select ON public.ticket_types;
CREATE POLICY ticket_types_public_select ON public.ticket_types
  FOR SELECT TO public USING (
    public.is_event_public(event_id) AND is_active AND status = 'active'
  );
DROP POLICY IF EXISTS ticket_types_member_select ON public.ticket_types;
CREATE POLICY ticket_types_member_select ON public.ticket_types
  FOR SELECT TO authenticated USING (public.can_access_event(event_id));
DROP POLICY IF EXISTS ticket_types_write ON public.ticket_types;
CREATE POLICY ticket_types_write ON public.ticket_types
  FOR ALL TO authenticated
  USING (public.can_manage_event(event_id)) WITH CHECK (public.can_manage_event(event_id));

DROP POLICY IF EXISTS ticket_inventory_public_select ON public.ticket_inventory;
CREATE POLICY ticket_inventory_public_select ON public.ticket_inventory
  FOR SELECT TO public USING (
    EXISTS (
      SELECT 1 FROM public.ticket_types tt
      WHERE tt.id = ticket_inventory.ticket_type_id
        AND tt.is_active
        AND tt.status = 'active'
        AND public.is_event_public(tt.event_id)
    )
  );
DROP POLICY IF EXISTS ticket_inventory_member_select ON public.ticket_inventory;
CREATE POLICY ticket_inventory_member_select ON public.ticket_inventory
  FOR SELECT TO authenticated USING (
    EXISTS (
      SELECT 1 FROM public.ticket_types tt
      WHERE tt.id = ticket_inventory.ticket_type_id
        AND public.can_access_event(tt.event_id)
    )
  );

-- Reservations are read-only to clients; checkout code will use a server-side role later.
DROP POLICY IF EXISTS reservations_select ON public.ticket_inventory_reservations;
CREATE POLICY reservations_select ON public.ticket_inventory_reservations
  FOR SELECT TO authenticated USING (public.can_access_reservation(id));
DROP POLICY IF EXISTS reservations_admin_write ON public.ticket_inventory_reservations;
CREATE POLICY reservations_admin_write ON public.ticket_inventory_reservations
  FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());

-- Orders and order items: customer-only, organizer-event-only, admin-only.
DROP POLICY IF EXISTS orders_select ON public.orders;
CREATE POLICY orders_select ON public.orders
  FOR SELECT TO authenticated USING (public.can_access_order(id));
DROP POLICY IF EXISTS order_items_select ON public.order_items;
CREATE POLICY order_items_select ON public.order_items
  FOR SELECT TO authenticated USING (public.can_access_order(order_id));

-- Payments: buyers and event owners/staff assigned to the event may see status metadata.
DROP POLICY IF EXISTS payments_select ON public.payments;
CREATE POLICY payments_select ON public.payments
  FOR SELECT TO authenticated USING (public.can_access_order(order_id));
DROP POLICY IF EXISTS webhooks_admin_select ON public.payment_webhook_events;
CREATE POLICY webhooks_admin_select ON public.payment_webhook_events
  FOR SELECT TO authenticated USING (public.is_admin());

-- Tickets: only the customer, event owner/staff, or admin.
DROP POLICY IF EXISTS tickets_select ON public.tickets;
CREATE POLICY tickets_select ON public.tickets
  FOR SELECT TO authenticated USING (public.can_view_ticket(id));
DROP POLICY IF EXISTS checkins_select ON public.ticket_checkins;
CREATE POLICY checkins_select ON public.ticket_checkins
  FOR SELECT TO authenticated USING (
    public.can_view_ticket(ticket_id) OR public.can_checkin_event(event_id)
  );
DROP POLICY IF EXISTS checkins_insert ON public.ticket_checkins;
CREATE POLICY checkins_insert ON public.ticket_checkins
  FOR INSERT TO authenticated WITH CHECK (
    scanned_by = auth.uid() AND public.can_checkin_event(event_id)
  );
DROP POLICY IF EXISTS checkins_update ON public.ticket_checkins;
CREATE POLICY checkins_update ON public.ticket_checkins
  FOR UPDATE TO authenticated
  USING (public.can_checkin_event(event_id) AND scanned_by = auth.uid())
  WITH CHECK (public.can_checkin_event(event_id) AND scanned_by = auth.uid());
DROP POLICY IF EXISTS checkins_delete ON public.ticket_checkins;
CREATE POLICY checkins_delete ON public.ticket_checkins
  FOR DELETE TO authenticated USING (public.is_admin());

-- Finance: refunds are admin-only; organizers can view their own commission/payout records.
DROP POLICY IF EXISTS refunds_admin_select ON public.refunds;
CREATE POLICY refunds_admin_select ON public.refunds
  FOR SELECT TO authenticated USING (public.is_admin());
DROP POLICY IF EXISTS commissions_select ON public.organizer_commissions;
CREATE POLICY commissions_select ON public.organizer_commissions
  FOR SELECT TO authenticated USING (public.is_admin() OR public.owns_organizer(organizer_id));
DROP POLICY IF EXISTS payouts_select ON public.organizer_payouts;
CREATE POLICY payouts_select ON public.organizer_payouts
  FOR SELECT TO authenticated USING (public.is_admin() OR public.owns_organizer(organizer_id));

-- Notifications: strictly per-user, no cross-customer reads.
DROP POLICY IF EXISTS notifications_select ON public.notifications;
CREATE POLICY notifications_select ON public.notifications
  FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.is_admin());
DROP POLICY IF EXISTS notifications_update ON public.notifications;
CREATE POLICY notifications_update ON public.notifications
  FOR UPDATE TO authenticated
  USING (user_id = auth.uid() OR public.is_admin())
  WITH CHECK (user_id = auth.uid() OR public.is_admin());
DROP POLICY IF EXISTS notifications_insert ON public.notifications;
CREATE POLICY notifications_insert ON public.notifications
  FOR INSERT TO authenticated WITH CHECK (public.is_admin());
DROP POLICY IF EXISTS notifications_delete ON public.notifications;
CREATE POLICY notifications_delete ON public.notifications
  FOR DELETE TO authenticated USING (public.is_admin());

-- Reviews: public only when approved; authors see their own pending review.
DROP POLICY IF EXISTS reviews_public_select ON public.reviews;
CREATE POLICY reviews_public_select ON public.reviews
  FOR SELECT TO public USING (status = 'approved');
DROP POLICY IF EXISTS reviews_owner_select ON public.reviews;
CREATE POLICY reviews_owner_select ON public.reviews
  FOR SELECT TO authenticated USING (customer_id = auth.uid() OR public.can_access_event(event_id));
DROP POLICY IF EXISTS reviews_insert ON public.reviews;
CREATE POLICY reviews_insert ON public.reviews
  FOR INSERT TO authenticated WITH CHECK (customer_id = auth.uid() AND status = 'pending');
DROP POLICY IF EXISTS reviews_moderate ON public.reviews;
CREATE POLICY reviews_moderate ON public.reviews
  FOR UPDATE TO authenticated
  USING (public.is_admin() OR public.can_manage_event(event_id))
  WITH CHECK (public.is_admin() OR public.can_manage_event(event_id));
DROP POLICY IF EXISTS reviews_delete ON public.reviews;
CREATE POLICY reviews_delete ON public.reviews
  FOR DELETE TO authenticated USING (
    public.is_admin() OR (customer_id = auth.uid() AND status = 'pending')
  );

-- Platform settings: only is_public values are visible to anonymous clients.
DROP POLICY IF EXISTS platform_settings_select ON public.platform_settings;
CREATE POLICY platform_settings_select ON public.platform_settings
  FOR SELECT TO public USING (is_public OR public.is_admin());
DROP POLICY IF EXISTS platform_settings_write ON public.platform_settings;
CREATE POLICY platform_settings_write ON public.platform_settings
  FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());

-- Audit log: read-only to admins; writes come from server-side code only.
DROP POLICY IF EXISTS audit_logs_admin_select ON public.audit_logs;
CREATE POLICY audit_logs_admin_select ON public.audit_logs
  FOR SELECT TO authenticated USING (public.is_admin());

-- ===== 0012_storage_buckets_and_policies.sql =====
-- Phase 1 / 0012: Supabase Storage buckets and object-level policies.
-- Path conventions:
--   event-images/{event_id}/{filename}
--   event-gallery/{event_id}/{filename}
--   organizer-logos/{organizer_id}/{filename}
--   user-avatars/{auth_user_id}/{filename}
--   ticket-files/{order_id}/{ticket_id}/{filename}

-- These helpers are also defined in 0010. They are repeated here with
-- CREATE OR REPLACE so this storage migration can be applied on its own
-- without failing with "function public.is_admin() does not exist".
-- Re-running 0010 later simply restores the same definitions.

CREATE OR REPLACE FUNCTION public.is_service_role()
RETURNS boolean
LANGUAGE sql
STABLE
SET search_path = public, pg_temp
AS $$
  SELECT coalesce(auth.jwt() ->> 'role', current_setting('request.jwt.claim.role', true), '') = 'service_role';
$$;

CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT public.is_service_role() OR EXISTS (
    SELECT 1
    FROM public.user_roles ur
    JOIN public.roles r ON r.id = ur.role_id
    WHERE ur.user_id = auth.uid() AND r.name = 'admin'
  );
$$;

CREATE OR REPLACE FUNCTION public.has_role(p_role public.app_role)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT public.is_service_role() OR EXISTS (
    SELECT 1
    FROM public.user_roles ur
    JOIN public.roles r ON r.id = ur.role_id
    WHERE ur.user_id = auth.uid() AND r.name = p_role
  );
$$;

CREATE OR REPLACE FUNCTION public.owns_organizer(p_organizer_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.organizers o
    WHERE o.id = p_organizer_id AND o.owner_id = auth.uid()
  );
$$;

CREATE OR REPLACE FUNCTION public.can_manage_organizer(p_organizer_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT public.is_admin()
    OR (public.has_role('organizer') AND public.owns_organizer(p_organizer_id));
$$;

CREATE OR REPLACE FUNCTION public.can_manage_event(p_event_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT public.is_admin()
    OR (
      public.has_role('organizer')
      AND public.owns_organizer((SELECT e.organizer_id FROM public.events e WHERE e.id = p_event_id))
    );
$$;

CREATE OR REPLACE FUNCTION public.owns_order(p_order_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.orders o
    WHERE o.id = p_order_id
      AND (
        o.customer_id = auth.uid()
        OR (o.buyer_email IS NOT NULL AND lower(o.buyer_email) = lower(coalesce(auth.jwt() ->> 'email', '')))
      )
  );
$$;

CREATE OR REPLACE FUNCTION public.storage_path_uuid(p_name text)
RETURNS uuid
LANGUAGE sql
IMMUTABLE
SET search_path = public, pg_temp
AS $$
  SELECT CASE
    WHEN split_part(p_name, '/', 1) ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    THEN split_part(p_name, '/', 1)::uuid
    ELSE NULL
  END;
$$;

CREATE OR REPLACE FUNCTION public.storage_path_owned_by_user(p_name text)
RETURNS boolean
LANGUAGE sql
STABLE
SET search_path = public, pg_temp
AS $$
  SELECT split_part(p_name, '/', 1) = auth.uid()::text;
$$;

INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES
  ('event-images', 'event-images', true, 10 * 1024 * 1024, ARRAY['image/jpeg', 'image/png', 'image/webp', 'image/avif']),
  ('event-gallery', 'event-gallery', true, 10 * 1024 * 1024, ARRAY['image/jpeg', 'image/png', 'image/webp', 'image/avif']),
  ('organizer-logos', 'organizer-logos', true, 5 * 1024 * 1024, ARRAY['image/jpeg', 'image/png', 'image/webp', 'image/svg+xml']),
  ('user-avatars', 'user-avatars', true, 5 * 1024 * 1024, ARRAY['image/jpeg', 'image/png', 'image/webp']),
  ('ticket-files', 'ticket-files', false, 10 * 1024 * 1024, ARRAY['application/pdf', 'image/jpeg', 'image/png'])
ON CONFLICT (id) DO NOTHING;

-- Supabase enables RLS on storage.objects by default and, since April 2025,
-- blocks ALTER TABLE on storage-owned tables for project roles. Do not add
-- an ENABLE ROW LEVEL SECURITY statement here; only the policies below are
-- needed and are permitted by Supabase.

-- Public read is granted only through buckets explicitly marked public.
DROP POLICY IF EXISTS storage_public_asset_read ON storage.objects;
CREATE POLICY storage_public_asset_read ON storage.objects
  FOR SELECT TO public USING (
    EXISTS (
      SELECT 1 FROM storage.buckets b
      WHERE b.id = storage.objects.bucket_id AND b.public = true
    )
  );

-- Private ticket files require order ownership or administrator access.
DROP POLICY IF EXISTS storage_private_asset_read ON storage.objects;
CREATE POLICY storage_private_asset_read ON storage.objects
  FOR SELECT TO authenticated USING (
    bucket_id = 'ticket-files'
    AND (
      public.is_admin()
      OR public.owns_order(public.storage_path_uuid(storage.objects.name))
    )
  );

-- Event image writers must own/manage the event identified by the first path segment.
DROP POLICY IF EXISTS storage_event_asset_insert ON storage.objects;
CREATE POLICY storage_event_asset_insert ON storage.objects
  FOR INSERT TO authenticated WITH CHECK (
    bucket_id IN ('event-images', 'event-gallery')
    AND (public.is_admin() OR public.can_manage_event(public.storage_path_uuid(name)))
  );
DROP POLICY IF EXISTS storage_event_asset_update ON storage.objects;
CREATE POLICY storage_event_asset_update ON storage.objects
  FOR UPDATE TO authenticated
  USING (
    bucket_id IN ('event-images', 'event-gallery')
    AND (public.is_admin() OR public.can_manage_event(public.storage_path_uuid(name)))
  )
  WITH CHECK (
    bucket_id IN ('event-images', 'event-gallery')
    AND (public.is_admin() OR public.can_manage_event(public.storage_path_uuid(name)))
  );
DROP POLICY IF EXISTS storage_event_asset_delete ON storage.objects;
CREATE POLICY storage_event_asset_delete ON storage.objects
  FOR DELETE TO authenticated USING (
    bucket_id IN ('event-images', 'event-gallery')
    AND (public.is_admin() OR public.can_manage_event(public.storage_path_uuid(name)))
  );

-- Organizer logo writes are restricted to the organizer owner/admin.
DROP POLICY IF EXISTS storage_organizer_logo_insert ON storage.objects;
CREATE POLICY storage_organizer_logo_insert ON storage.objects
  FOR INSERT TO authenticated WITH CHECK (
    bucket_id = 'organizer-logos'
    AND (public.is_admin() OR public.can_manage_organizer(public.storage_path_uuid(name)))
  );
DROP POLICY IF EXISTS storage_organizer_logo_update ON storage.objects;
CREATE POLICY storage_organizer_logo_update ON storage.objects
  FOR UPDATE TO authenticated
  USING (
    bucket_id = 'organizer-logos'
    AND (public.is_admin() OR public.can_manage_organizer(public.storage_path_uuid(name)))
  )
  WITH CHECK (
    bucket_id = 'organizer-logos'
    AND (public.is_admin() OR public.can_manage_organizer(public.storage_path_uuid(name)))
  );
DROP POLICY IF EXISTS storage_organizer_logo_delete ON storage.objects;
CREATE POLICY storage_organizer_logo_delete ON storage.objects
  FOR DELETE TO authenticated USING (
    bucket_id = 'organizer-logos'
    AND (public.is_admin() OR public.can_manage_organizer(public.storage_path_uuid(name)))
  );

-- Avatars are public to read but writable only inside the signed-in user's folder.
DROP POLICY IF EXISTS storage_avatar_insert ON storage.objects;
CREATE POLICY storage_avatar_insert ON storage.objects
  FOR INSERT TO authenticated WITH CHECK (
    bucket_id = 'user-avatars'
    AND (public.is_admin() OR public.storage_path_owned_by_user(name))
  );
DROP POLICY IF EXISTS storage_avatar_update ON storage.objects;
CREATE POLICY storage_avatar_update ON storage.objects
  FOR UPDATE TO authenticated
  USING (
    bucket_id = 'user-avatars'
    AND (public.is_admin() OR public.storage_path_owned_by_user(name))
  )
  WITH CHECK (
    bucket_id = 'user-avatars'
    AND (public.is_admin() OR public.storage_path_owned_by_user(name))
  );
DROP POLICY IF EXISTS storage_avatar_delete ON storage.objects;
CREATE POLICY storage_avatar_delete ON storage.objects
  FOR DELETE TO authenticated USING (
    bucket_id = 'user-avatars'
    AND (public.is_admin() OR public.storage_path_owned_by_user(name))
  );

-- Ticket files are private; only the order owner/admin may add or remove them.
DROP POLICY IF EXISTS storage_ticket_file_insert ON storage.objects;
CREATE POLICY storage_ticket_file_insert ON storage.objects
  FOR INSERT TO authenticated WITH CHECK (
    bucket_id = 'ticket-files'
    AND (
      public.is_admin()
      OR public.owns_order(public.storage_path_uuid(name))
    )
  );
DROP POLICY IF EXISTS storage_ticket_file_update ON storage.objects;
CREATE POLICY storage_ticket_file_update ON storage.objects
  FOR UPDATE TO authenticated
  USING (
    bucket_id = 'ticket-files'
    AND (
      public.is_admin()
      OR public.owns_order(public.storage_path_uuid(name))
    )
  )
  WITH CHECK (
    bucket_id = 'ticket-files'
    AND (
      public.is_admin()
      OR public.owns_order(public.storage_path_uuid(name))
    )
  );
DROP POLICY IF EXISTS storage_ticket_file_delete ON storage.objects;
CREATE POLICY storage_ticket_file_delete ON storage.objects
  FOR DELETE TO authenticated USING (
    bucket_id = 'ticket-files'
    AND (
      public.is_admin()
      OR public.owns_order(public.storage_path_uuid(name))
    )
  );

-- ===== 0013_admin_auth_and_invitations.sql =====
-- Phase 2 / 0013: auth profile creation and invite-only admin registration.
-- The raw invite token is generated in the client and never sent to the database;
-- only its SHA-256 hex hash is stored and compared.
-- No user can assign themselves the admin role: the secure function validates a
-- single-use, unexpired invitation that matches the new auth user's email.

CREATE TABLE IF NOT EXISTS public.admin_invitations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  email text NOT NULL,
  token_hash text NOT NULL UNIQUE,
  invited_by uuid REFERENCES public.profiles (id) ON DELETE SET NULL,
  expires_at timestamptz NOT NULL,
  used_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT admin_invitations_email_format CHECK (
    email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
  ),
  CONSTRAINT admin_invitations_token_hash CHECK (token_hash ~ '^[a-f0-9]{64}$'),
  CONSTRAINT admin_invitations_expiry_future CHECK (expires_at > created_at)
);

CREATE INDEX IF NOT EXISTS admin_invitations_email_idx
  ON public.admin_invitations (lower(email));
CREATE INDEX IF NOT EXISTS admin_invitations_unused_idx
  ON public.admin_invitations (expires_at) WHERE used_at IS NULL;

ALTER TABLE public.admin_invitations ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS admin_invitations_admin_select ON public.admin_invitations;
CREATE POLICY admin_invitations_admin_select ON public.admin_invitations
  FOR SELECT TO authenticated USING (public.is_admin());

-- Supabase Auth trigger: create a profile for every new auth user.
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  INSERT INTO public.profiles (id, email, full_name)
  VALUES (
    NEW.id,
    NEW.email,
    coalesce(nullif(btrim(NEW.raw_user_meta_data ->> 'full_name'), ''), split_part(NEW.email, '@', 1))
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

-- Refresh the self-escalation guard so a validated invitation can insert exactly
-- one admin role assignment without allowing ordinary self-assignment.
CREATE OR REPLACE FUNCTION public.prevent_user_role_self_escalation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF TG_OP IN ('INSERT', 'UPDATE')
     AND NEW.user_id = auth.uid()
     AND NOT public.is_service_role()
     AND coalesce(current_setting('app.admin_invite_accepted', true), '') <> 'true'
     AND EXISTS (
       SELECT 1 FROM public.roles r
       WHERE r.id = NEW.role_id AND r.name IN ('admin', 'organizer')
     ) THEN
    RAISE EXCEPTION 'Self-assignment of admin/organizer roles is not allowed';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.create_admin_invitation(
  p_email text,
  p_token_hash text,
  p_expires_in interval DEFAULT interval '7 days'
)
RETURNS public.admin_invitations
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_result public.admin_invitations;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Only administrators can create admin invitations';
  END IF;
  IF p_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' THEN
    RAISE EXCEPTION 'Invalid invitation email';
  END IF;
  IF p_token_hash !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'Invalid invitation token hash';
  END IF;
  IF p_expires_in IS NULL OR p_expires_in <= interval '0' THEN
    RAISE EXCEPTION 'Invitation lifetime must be positive';
  END IF;

  INSERT INTO public.admin_invitations (email, token_hash, invited_by, expires_at)
  VALUES (p_email, p_token_hash, auth.uid(), now() + p_expires_in)
  RETURNING * INTO v_result;

  RETURN v_result;
END;
$$;

CREATE OR REPLACE FUNCTION public.accept_admin_invitation(
  p_user_id uuid,
  p_token_hash text
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_invitation public.admin_invitations;
BEGIN
  IF p_token_hash !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'Invalid invitation token hash';
  END IF;

  SELECT * INTO v_invitation
  FROM public.admin_invitations
  WHERE token_hash = p_token_hash
  FOR UPDATE;

  IF NOT FOUND OR v_invitation.used_at IS NOT NULL OR v_invitation.expires_at <= now() THEN
    RAISE EXCEPTION 'Invitation is invalid, expired, or already used';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM auth.users u
    WHERE u.id = p_user_id AND lower(u.email) = lower(v_invitation.email)
  ) THEN
    RAISE EXCEPTION 'Invitation email does not match this account';
  END IF;

  UPDATE public.admin_invitations
  SET used_at = now()
  WHERE id = v_invitation.id;

  BEGIN
    PERFORM set_config('app.admin_invite_accepted', 'true', true);
    INSERT INTO public.user_roles (user_id, role_id, assigned_by)
    SELECT p_user_id, r.id, v_invitation.invited_by
    FROM public.roles r
    WHERE r.name = 'admin'
    ON CONFLICT (user_id, role_id) DO NOTHING;
    PERFORM set_config('app.admin_invite_accepted', '', true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('app.admin_invite_accepted', '', true);
    RAISE;
  END;

  RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION public.create_admin_invitation(text, text, interval) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.accept_admin_invitation(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_admin_invitation(text, text, interval) TO authenticated;
GRANT EXECUTE ON FUNCTION public.accept_admin_invitation(uuid, text) TO anon, authenticated;

-- ===== 0014_admin_management_writes.sql =====
-- Phase 2 / 0014: controlled administrative record management.
-- Orders and payouts are readable by admins already; this adds narrow UPDATE
-- rights for operational status changes only. Money, ownership and currency
-- fields remain immutable from the client. Payment records and refunds stay
-- write-only for trusted server/webhook code.

DROP POLICY IF EXISTS orders_admin_update ON public.orders;
CREATE POLICY orders_admin_update ON public.orders
  FOR UPDATE TO authenticated
  USING (public.is_admin())
  WITH CHECK (public.is_admin());

DROP POLICY IF EXISTS payouts_admin_update ON public.organizer_payouts;
CREATE POLICY payouts_admin_update ON public.organizer_payouts
  FOR UPDATE TO authenticated
  USING (public.is_admin())
  WITH CHECK (public.is_admin());

CREATE OR REPLACE FUNCTION public.enforce_admin_order_update()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Only administrators can update order status';
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.order_number IS DISTINCT FROM OLD.order_number
     OR NEW.customer_id IS DISTINCT FROM OLD.customer_id
     OR NEW.event_id IS DISTINCT FROM OLD.event_id
     OR NEW.currency IS DISTINCT FROM OLD.currency
     OR NEW.subtotal_amount IS DISTINCT FROM OLD.subtotal_amount
     OR NEW.discount_amount IS DISTINCT FROM OLD.discount_amount
     OR NEW.fee_amount IS DISTINCT FROM OLD.fee_amount
     OR NEW.total_amount IS DISTINCT FROM OLD.total_amount
     OR NEW.buyer_name IS DISTINCT FROM OLD.buyer_name
     OR NEW.buyer_email IS DISTINCT FROM OLD.buyer_email
     OR NEW.buyer_phone IS DISTINCT FROM OLD.buyer_phone
     OR NEW.expires_at IS DISTINCT FROM OLD.expires_at
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'Order amounts, identity and currency are immutable';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_enforce_admin_order_update ON public.orders;
CREATE TRIGGER trg_enforce_admin_order_update
  BEFORE UPDATE ON public.orders
  FOR EACH ROW EXECUTE FUNCTION public.enforce_admin_order_update();

CREATE OR REPLACE FUNCTION public.enforce_admin_payout_update()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Only administrators can update payout status';
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.organizer_id IS DISTINCT FROM OLD.organizer_id
     OR NEW.payout_reference IS DISTINCT FROM OLD.payout_reference
     OR NEW.amount IS DISTINCT FROM OLD.amount
     OR NEW.currency IS DISTINCT FROM OLD.currency
     OR NEW.requested_at IS DISTINCT FROM OLD.requested_at
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'Payout amount, owner and currency are immutable';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_enforce_admin_payout_update ON public.organizer_payouts;
CREATE TRIGGER trg_enforce_admin_payout_update
  BEFORE UPDATE ON public.organizer_payouts
  FOR EACH ROW EXECUTE FUNCTION public.enforce_admin_payout_update();

-- Append-only audit entries for administrative mutations. Client code has no
-- INSERT/UPDATE/DELETE policy on audit_logs; only these SECURITY DEFINER
-- triggers write to it.
CREATE OR REPLACE FUNCTION public.log_admin_mutation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_role public.app_role;
  v_entity_id uuid;
  v_changes jsonb;
BEGIN
  SELECT r.name INTO v_role
  FROM public.user_roles ur
  JOIN public.roles r ON r.id = ur.role_id
  WHERE ur.user_id = auth.uid() AND r.name = 'admin'
  LIMIT 1;

  IF v_role IS NULL THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'DELETE' THEN
    v_entity_id := (to_jsonb(OLD) ->> 'id')::uuid;
    v_changes := to_jsonb(OLD);
  ELSE
    v_entity_id := (to_jsonb(NEW) ->> 'id')::uuid;
    v_changes := jsonb_build_object('before', to_jsonb(OLD), 'after', to_jsonb(NEW));
  END IF;

  INSERT INTO public.audit_logs (actor_id, actor_role, action, entity_type, entity_id, changes)
  VALUES (auth.uid(), v_role, TG_OP || ':' || TG_TABLE_NAME, TG_TABLE_NAME, v_entity_id, v_changes);
  RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS trg_audit_profiles ON public.profiles;
CREATE TRIGGER trg_audit_profiles AFTER UPDATE OR DELETE ON public.profiles
  FOR EACH ROW EXECUTE FUNCTION public.log_admin_mutation();

DROP TRIGGER IF EXISTS trg_audit_organizers ON public.organizers;
CREATE TRIGGER trg_audit_organizers AFTER UPDATE OR DELETE ON public.organizers
  FOR EACH ROW EXECUTE FUNCTION public.log_admin_mutation();

DROP TRIGGER IF EXISTS trg_audit_events ON public.events;
CREATE TRIGGER trg_audit_events AFTER UPDATE OR DELETE ON public.events
  FOR EACH ROW EXECUTE FUNCTION public.log_admin_mutation();

DROP TRIGGER IF EXISTS trg_audit_orders ON public.orders;
CREATE TRIGGER trg_audit_orders AFTER UPDATE OR DELETE ON public.orders
  FOR EACH ROW EXECUTE FUNCTION public.log_admin_mutation();

DROP TRIGGER IF EXISTS trg_audit_payouts ON public.organizer_payouts;
CREATE TRIGGER trg_audit_payouts AFTER UPDATE OR DELETE ON public.organizer_payouts
  FOR EACH ROW EXECUTE FUNCTION public.log_admin_mutation();

DROP TRIGGER IF EXISTS trg_audit_reviews ON public.reviews;
CREATE TRIGGER trg_audit_reviews AFTER UPDATE OR DELETE ON public.reviews
  FOR EACH ROW EXECUTE FUNCTION public.log_admin_mutation();

-- ===== 0015_storefront_event_showcase.sql =====
-- Phase 2 / 0015: admin-managed storefront event showcase.
--
-- The normalized `events` table remains the source of truth for inventory,
-- orders and finance. This table owns only the presentation data used by the
-- storefront: upcoming/ongoing/past grouping, carousel selection and the
-- display fields shown on event cards and detail pages.

-- Helpers from 0010 are repeated here with CREATE OR REPLACE so this
-- migration can also be applied on its own without failing with
-- "function public.set_updated_at() does not exist" or
-- "function public.is_admin() does not exist".

CREATE OR REPLACE FUNCTION public.set_updated_at()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.is_service_role()
RETURNS boolean
LANGUAGE sql
STABLE
SET search_path = public, pg_temp
AS $$
  SELECT coalesce(auth.jwt() ->> 'role', current_setting('request.jwt.claim.role', true), '') = 'service_role';
$$;

CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT public.is_service_role() OR EXISTS (
    SELECT 1
    FROM public.user_roles ur
    JOIN public.roles r ON r.id = ur.role_id
    WHERE ur.user_id = auth.uid() AND r.name = 'admin'
  );
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_type
    WHERE typname = 'storefront_event_group' AND typnamespace = 'public'::regnamespace
  ) THEN
    CREATE TYPE public.storefront_event_group AS ENUM ('past', 'upcoming', 'ongoing');
  END IF;
END $$;

CREATE TABLE IF NOT EXISTS public.storefront_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug text NOT NULL UNIQUE,
  title text NOT NULL,
  category text NOT NULL,
  event_group public.storefront_event_group NOT NULL DEFAULT 'upcoming',
  display_order integer NOT NULL DEFAULT 0,
  is_visible boolean NOT NULL DEFAULT true,
  status_label text NOT NULL DEFAULT 'On sale now',
  date_label text NOT NULL,
  date_value date NOT NULL,
  time_label text,
  venue text,
  location text,
  city text,
  price_amount numeric(14, 2) NOT NULL DEFAULT 0,
  currency text NOT NULL DEFAULT 'BDT',
  image_url text,
  image_alt text,
  about text,
  lineup jsonb NOT NULL DEFAULT '[]'::jsonb,
  is_carousel boolean NOT NULL DEFAULT false,
  carousel_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT storefront_events_slug_format CHECK (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  CONSTRAINT storefront_events_title_not_blank CHECK (length(btrim(title)) > 0),
  CONSTRAINT storefront_events_category_not_blank CHECK (length(btrim(category)) > 0),
  CONSTRAINT storefront_events_status_not_blank CHECK (length(btrim(status_label)) > 0),
  CONSTRAINT storefront_events_date_not_blank CHECK (length(btrim(date_label)) > 0),
  CONSTRAINT storefront_events_price_nonnegative CHECK (price_amount >= 0),
  CONSTRAINT storefront_events_currency_format CHECK (currency ~ '^[A-Z]{3}$'),
  CONSTRAINT storefront_events_lineup_array CHECK (jsonb_typeof(lineup) = 'array'),
  CONSTRAINT storefront_events_display_order_nonnegative CHECK (display_order >= 0),
  CONSTRAINT storefront_events_carousel_order_nonnegative CHECK (carousel_order >= 0)
);

COMMENT ON TABLE public.storefront_events IS 'Admin-managed presentation records for the storefront. Not used for inventory, orders or payments.';
COMMENT ON COLUMN public.storefront_events.event_group IS 'Where the event appears on the storefront: upcoming, ongoing or past archive.';
COMMENT ON COLUMN public.storefront_events.is_carousel IS 'Include this event in the storefront coverflow carousel.';

DROP TRIGGER IF EXISTS trg_set_updated_at ON public.storefront_events;
CREATE TRIGGER trg_set_updated_at BEFORE UPDATE ON public.storefront_events
FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE INDEX IF NOT EXISTS storefront_events_group_order_idx
  ON public.storefront_events (event_group, display_order)
  WHERE is_visible;

CREATE INDEX IF NOT EXISTS storefront_events_carousel_idx
  ON public.storefront_events (carousel_order)
  WHERE is_visible AND is_carousel;

ALTER TABLE public.storefront_events ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS storefront_events_public_select ON public.storefront_events;
CREATE POLICY storefront_events_public_select ON public.storefront_events
FOR SELECT TO anon, authenticated
USING (is_visible);

DROP POLICY IF EXISTS storefront_events_admin_all ON public.storefront_events;
CREATE POLICY storefront_events_admin_all ON public.storefront_events
FOR ALL TO authenticated
USING (public.is_admin())
WITH CHECK (public.is_admin());

