    RAISE EXCEPTION 'Enter a valid name.' USING ERRCODE = '22023';
  END IF;
  IF v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' THEN
    RAISE EXCEPTION 'Enter a valid email address.' USING ERRCODE = '22023';
  END IF;
  IF lower(v_email) <> lower(coalesce(auth.jwt() ->> 'email', '')) THEN
    RAISE EXCEPTION 'Use the email address on your TickShow account.' USING ERRCODE = '22023';
  END IF;
  IF length(v_phone) NOT BETWEEN 7 AND 32 THEN
    RAISE EXCEPTION 'Enter a valid phone number.' USING ERRCODE = '22023';
  END IF;

  SELECT e.id, e.slug, e.title, e.date_label, e.time_label, e.venue, e.location,
         e.price_amount, e.currency
  INTO v_event_id, v_event_slug, v_event_title, v_event_date_label, v_event_time_label,
       v_event_venue, v_event_location, v_unit_price, v_currency
  FROM public.storefront_events AS e
  WHERE e.slug = p_event_slug
    AND e.is_visible
    AND e.event_group <> 'past'
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'This event is no longer available for booking.' USING ERRCODE = '22023';
  END IF;

  v_reference := 'TS-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));

  INSERT INTO public.storefront_bookings (
    booking_reference, storefront_event_id, customer_id, event_slug, event_title,
    event_date_label, event_time_label, event_venue, event_location,
    quantity, unit_price_amount, total_amount, currency,
    buyer_name, buyer_email, buyer_phone, is_demo
  )
  VALUES (
    v_reference, v_event_id, v_customer_id, v_event_slug, v_event_title,
    v_event_date_label, v_event_time_label, v_event_venue, v_event_location,
    p_quantity, v_unit_price, v_unit_price * p_quantity, v_currency,
    v_name, v_email, v_phone, true
  );

  RETURN QUERY SELECT v_reference, v_unit_price * p_quantity;
END;
$$;

REVOKE ALL ON FUNCTION public.create_storefront_booking(text, integer, text, text, text)
FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.create_storefront_booking(text, integer, text, text, text)
TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.claim_storefront_ticket_email(
  p_booking_reference text,
  p_resend boolean DEFAULT false
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_booking public.storefront_bookings%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sign in to request your ticket email.' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_booking
  FROM public.storefront_bookings
  WHERE booking_reference = p_booking_reference
    AND customer_id = auth.uid()
    AND is_demo
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Demo booking not found.' USING ERRCODE = 'P0002';
  END IF;

  IF v_booking.ticket_email_status = 'sending'
     OR (v_booking.ticket_email_status = 'sent' AND NOT coalesce(p_resend, false)) THEN
    RETURN false;
  END IF;

  UPDATE public.storefront_bookings
  SET ticket_email_status = 'sending'
  WHERE id = v_booking.id;
  RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION public.claim_storefront_ticket_email(text, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.claim_storefront_ticket_email(text, boolean) TO authenticated;

CREATE OR REPLACE FUNCTION public.finish_storefront_ticket_email(
  p_booking_reference text,
  p_sent boolean
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sign in to update ticket delivery.' USING ERRCODE = '28000';
  END IF;

  UPDATE public.storefront_bookings
  SET ticket_email_status = CASE WHEN p_sent THEN 'sent' ELSE 'failed' END,
      ticket_emailed_at = CASE WHEN p_sent THEN now() ELSE ticket_emailed_at END
  WHERE booking_reference = p_booking_reference
    AND customer_id = auth.uid()
    AND is_demo
    AND ticket_email_status = 'sending';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket delivery state could not be updated.' USING ERRCODE = 'P0002';
  END IF;
END;
$$;

REVOKE ALL ON FUNCTION public.finish_storefront_ticket_email(text, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.finish_storefront_ticket_email(text, boolean) TO authenticated;

CREATE OR REPLACE FUNCTION public.claim_storefront_ticket_assets(
  p_booking_reference text,
  p_force boolean DEFAULT false
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_booking public.storefront_bookings%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sign in to prepare your ticket.' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_booking
  FROM public.storefront_bookings
  WHERE booking_reference = p_booking_reference
    AND customer_id = auth.uid()
    AND is_demo
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Demo booking not found.' USING ERRCODE = 'P0002';
  END IF;

  IF v_booking.ticket_assets_status = 'ready' AND NOT coalesce(p_force, false) THEN
    RETURN false;
  END IF;
  IF v_booking.ticket_assets_status = 'generating'
     AND v_booking.ticket_assets_started_at > now() - interval '10 minutes' THEN
    RETURN false;
  END IF;

  UPDATE public.storefront_bookings
  SET ticket_assets_status = 'generating',
      ticket_assets_started_at = now()
  WHERE id = v_booking.id;
  RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION public.claim_storefront_ticket_assets(text, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.claim_storefront_ticket_assets(text, boolean) TO authenticated;

CREATE OR REPLACE FUNCTION public.finish_storefront_ticket_assets(
  p_booking_reference text,
  p_ready boolean
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sign in to update ticket preparation.' USING ERRCODE = '28000';
  END IF;

  UPDATE public.storefront_bookings
  SET ticket_assets_status = CASE WHEN p_ready THEN 'ready' ELSE 'pending' END,
      ticket_assets_started_at = NULL
  WHERE booking_reference = p_booking_reference
    AND customer_id = auth.uid()
    AND is_demo
    AND ticket_assets_status = 'generating';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ticket preparation state could not be updated.' USING ERRCODE = 'P0002';
  END IF;
END;
$$;

REVOKE ALL ON FUNCTION public.finish_storefront_ticket_assets(text, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.finish_storefront_ticket_assets(text, boolean) TO authenticated;

DROP FUNCTION IF EXISTS public.claim_storefront_ticket_download(text);

CREATE FUNCTION public.claim_storefront_ticket_download(p_booking_reference text)
RETURNS TABLE (claimed boolean, already_downloaded_at timestamptz)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_booking public.storefront_bookings%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sign in to download your ticket.' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_booking
  FROM public.storefront_bookings
  WHERE booking_reference = p_booking_reference
    AND customer_id = auth.uid()
    AND is_demo
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Demo ticket not found.' USING ERRCODE = 'P0002';
  END IF;

  IF v_booking.ticket_downloaded_at IS NOT NULL THEN
    RETURN QUERY SELECT false, v_booking.ticket_downloaded_at;
    RETURN;
  END IF;

  UPDATE public.storefront_bookings
  SET ticket_downloaded_at = now()
  WHERE id = v_booking.id;
  RETURN QUERY SELECT true, NULL::timestamptz;
END;
$$;

REVOKE ALL ON FUNCTION public.claim_storefront_ticket_download(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.claim_storefront_ticket_download(text) TO authenticated;

DROP FUNCTION IF EXISTS public.mark_storefront_ticket_emailed(text);

CREATE OR REPLACE FUNCTION public.verify_storefront_ticket_by_id(
  p_ticket_id uuid,
  p_ticket_token text
)
RETURNS TABLE (
  valid boolean,
  event_title text,
  event_date text,
  event_time text,
  event_venue text,
  event_location text,
  booking_reference text,
  ticket_number integer,
  already_checked_in boolean
)
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = public, extensions, pg_temp
AS $$
  WITH matched AS (
    SELECT t.revoked_at, t.checked_in_at, t.ticket_number, b.*
    FROM public.storefront_tickets AS t
    JOIN public.storefront_bookings AS b ON b.id = t.booking_id
    WHERE t.id = p_ticket_id
      AND p_ticket_token ~ '^[A-Za-z0-9_-]{32,128}$'
      AND t.token_hash = encode(
        extensions.digest(convert_to(p_ticket_token, 'UTF8'), 'sha256'),
        'hex'
      )
  )
  SELECT
    coalesce(m.revoked_at IS NULL AND m.checked_in_at IS NULL AND m.is_demo, false),
    m.event_title,
    m.event_date_label,
    m.event_time_label,
    m.event_venue,
    m.event_location,
    m.booking_reference,
    m.ticket_number,
    coalesce(m.checked_in_at IS NOT NULL, false)
  FROM (SELECT 1) AS requested
  LEFT JOIN matched AS m ON true;
$$;

REVOKE ALL ON FUNCTION public.verify_storefront_ticket_by_id(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.verify_storefront_ticket_by_id(uuid, text)
TO anon, authenticated, service_role;

-- Keep old booking-reference QR links working while validating their hashed token.
DROP FUNCTION IF EXISTS public.verify_storefront_ticket(text, text);

CREATE FUNCTION public.verify_storefront_ticket(
  p_booking_reference text,
  p_ticket_token text
)
RETURNS TABLE (
  valid boolean,
  event_title text,
  event_date text,
  event_venue text,
  event_location text,
  quantity integer
)
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = public, extensions, pg_temp
AS $$
  WITH matched AS (
    SELECT t.revoked_at, t.checked_in_at, b.*
    FROM public.storefront_tickets AS t
    JOIN public.storefront_bookings AS b ON b.id = t.booking_id
    WHERE b.booking_reference = p_booking_reference
      AND t.ticket_number = 1
      AND p_ticket_token ~ '^[A-Za-z0-9_-]{32,128}$'
      AND t.token_hash = encode(
        extensions.digest(convert_to(p_ticket_token, 'UTF8'), 'sha256'),
        'hex'
      )
  )
  SELECT
    coalesce(m.revoked_at IS NULL AND m.checked_in_at IS NULL AND m.is_demo, false),
    m.event_title,
    m.event_date_label,
    m.event_venue,
    m.event_location,
    m.quantity
  FROM (SELECT 1) AS requested
  LEFT JOIN matched AS m ON true;
$$;

REVOKE ALL ON FUNCTION public.verify_storefront_ticket(text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.verify_storefront_ticket(text, text)
TO anon, authenticated, service_role;

-- ===== 0023_link_showcase_events_to_catalog.sql =====
-- Create a normalized catalog event and one general-admission ticket type
-- whenever a showcase event is saved with complete operational details.

ALTER TABLE public.storefront_events
  ADD COLUMN IF NOT EXISTS normalized_event_id uuid
    REFERENCES public.events (id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS organizer_id uuid
    REFERENCES public.organizers (id) ON DELETE RESTRICT,
  ADD COLUMN IF NOT EXISTS starts_at timestamptz,
  ADD COLUMN IF NOT EXISTS ends_at timestamptz,
  ADD COLUMN IF NOT EXISTS capacity integer;

CREATE UNIQUE INDEX IF NOT EXISTS storefront_events_normalized_event_id_idx
  ON public.storefront_events (normalized_event_id)
  WHERE normalized_event_id IS NOT NULL;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'storefront_events_catalog_details_consistent'
      AND conrelid = 'public.storefront_events'::regclass
  ) THEN
    ALTER TABLE public.storefront_events
      ADD CONSTRAINT storefront_events_catalog_details_consistent CHECK (
        (
          organizer_id IS NULL
          AND starts_at IS NULL
          AND ends_at IS NULL
          AND capacity IS NULL
          AND normalized_event_id IS NULL
        )
        OR (
          organizer_id IS NOT NULL
          AND starts_at IS NOT NULL
          AND ends_at IS NOT NULL
          AND ends_at > starts_at
          AND capacity > 0
        )
      );
  END IF;
END
$$;

CREATE OR REPLACE FUNCTION public.sync_storefront_event_to_catalog()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_category_id uuid;
  v_event_id uuid;
  v_rows_updated integer;
  v_operational_fields_present boolean;
BEGIN
  IF TG_OP = 'UPDATE'
    AND ROW(
      NEW.title, NEW.slug, NEW.category, NEW.about, NEW.image_url, NEW.venue,
      NEW.location, NEW.city, NEW.price_amount, NEW.currency, NEW.organizer_id,
      NEW.starts_at, NEW.ends_at, NEW.capacity
    ) IS NOT DISTINCT FROM ROW(
      OLD.title, OLD.slug, OLD.category, OLD.about, OLD.image_url, OLD.venue,
      OLD.location, OLD.city, OLD.price_amount, OLD.currency, OLD.organizer_id,
      OLD.starts_at, OLD.ends_at, OLD.capacity
    )
  THEN
    RETURN NEW;
  END IF;

  v_operational_fields_present :=
    NEW.organizer_id IS NOT NULL
    OR NEW.starts_at IS NOT NULL
    OR NEW.ends_at IS NOT NULL
    OR NEW.capacity IS NOT NULL;

  IF NOT v_operational_fields_present AND NEW.normalized_event_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.organizer_id IS NULL
    OR NEW.starts_at IS NULL
    OR NEW.ends_at IS NULL
    OR NEW.capacity IS NULL
    OR NEW.ends_at <= NEW.starts_at
    OR NEW.capacity <= 0
  THEN
    RAISE EXCEPTION
      'Choose an organizer, valid event start/end times, and a positive ticket capacity.';
  END IF;

  SELECT id
  INTO v_category_id
  FROM public.event_categories
  WHERE lower(name) = lower(NEW.category)
  LIMIT 1;
  IF v_category_id IS NULL THEN
    RAISE EXCEPTION 'No event catalog category matches showcase category "%".', NEW.category;
  END IF;

  PERFORM 1
  FROM public.organizers
  WHERE id = NEW.organizer_id
    AND status = 'active'
    AND approval_status = 'approved';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Select an active, approved organizer.';
  END IF;

  IF NEW.normalized_event_id IS NULL THEN
    INSERT INTO public.events (
      organizer_id, category_id, created_by, title, slug, description,
      cover_image_url, venue_name, venue_address, venue_city, starts_at,
      ends_at, status, approval_status, capacity
    )
    VALUES (
      NEW.organizer_id, v_category_id, auth.uid(), NEW.title, NEW.slug,
      NEW.about, NEW.image_url, NEW.venue, NEW.location, NEW.city,
      NEW.starts_at, NEW.ends_at, 'draft', 'pending', NEW.capacity
    )
    RETURNING id INTO v_event_id;

    INSERT INTO public.ticket_types (
      event_id, name, price_amount, currency, quantity_total, max_per_order,
      sales_start_at, sales_end_at
    )
    VALUES (
      v_event_id, 'General Admission', NEW.price_amount, NEW.currency,
      NEW.capacity, least(8, NEW.capacity),
      least(now(), NEW.starts_at - interval '1 minute'), NEW.starts_at
    );

    NEW.normalized_event_id := v_event_id;
    RETURN NEW;
  END IF;

  UPDATE public.events
  SET organizer_id = NEW.organizer_id,
      category_id = v_category_id,
      title = NEW.title,
      slug = NEW.slug,
      description = NEW.about,
      cover_image_url = NEW.image_url,
      venue_name = NEW.venue,
      venue_address = NEW.location,
      venue_city = NEW.city,
      starts_at = NEW.starts_at,
      ends_at = NEW.ends_at,
      capacity = NEW.capacity
  WHERE id = NEW.normalized_event_id;
  GET DIAGNOSTICS v_rows_updated = ROW_COUNT;
  IF v_rows_updated = 0 THEN
    RAISE EXCEPTION 'The linked catalog event no longer exists.';
  END IF;

  UPDATE public.ticket_types
  SET price_amount = NEW.price_amount,
      currency = NEW.currency,
      quantity_total = NEW.capacity,
      max_per_order = least(8, NEW.capacity),
      sales_start_at = least(now(), NEW.starts_at - interval '1 minute'),
      sales_end_at = NEW.starts_at
  WHERE event_id = NEW.normalized_event_id
    AND name = 'General Admission';
  GET DIAGNOSTICS v_rows_updated = ROW_COUNT;
  IF v_rows_updated = 0 THEN
    RAISE EXCEPTION 'The linked General Admission ticket type no longer exists.';
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_sync_storefront_event_to_catalog ON public.storefront_events;
CREATE TRIGGER trg_sync_storefront_event_to_catalog
BEFORE INSERT OR UPDATE ON public.storefront_events
FOR EACH ROW EXECUTE FUNCTION public.sync_storefront_event_to_catalog();

-- ===== 0024_event_ticket_designs.sql =====
-- Store an event-specific ticket style and optional artwork, and snapshot both
-- onto bookings so later event edits do not change already-issued tickets.

ALTER TABLE public.storefront_events
  ADD COLUMN IF NOT EXISTS ticket_design_style text NOT NULL DEFAULT 'classic',
  ADD COLUMN IF NOT EXISTS ticket_design_image_path text;

ALTER TABLE public.storefront_bookings
  ADD COLUMN IF NOT EXISTS ticket_design_style text NOT NULL DEFAULT 'classic',
  ADD COLUMN IF NOT EXISTS ticket_design_image_path text;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'storefront_events_ticket_design_style_check'
      AND conrelid = 'public.storefront_events'::regclass
  ) THEN
    ALTER TABLE public.storefront_events
      ADD CONSTRAINT storefront_events_ticket_design_style_check
      CHECK (ticket_design_style IN ('classic', 'midnight', 'festival', 'neon'));
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'storefront_bookings_ticket_design_style_check'
      AND conrelid = 'public.storefront_bookings'::regclass
  ) THEN
    ALTER TABLE public.storefront_bookings
      ADD CONSTRAINT storefront_bookings_ticket_design_style_check
      CHECK (ticket_design_style IN ('classic', 'midnight', 'festival', 'neon'));
  END IF;
END
$$;

CREATE OR REPLACE FUNCTION public.snapshot_storefront_ticket_design()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF NEW.storefront_event_id IS NOT NULL THEN
    SELECT ticket_design_style, ticket_design_image_path
    INTO NEW.ticket_design_style, NEW.ticket_design_image_path
    FROM public.storefront_events
    WHERE id = NEW.storefront_event_id;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_snapshot_storefront_ticket_design
  ON public.storefront_bookings;
CREATE TRIGGER trg_snapshot_storefront_ticket_design
BEFORE INSERT ON public.storefront_bookings
FOR EACH ROW EXECUTE FUNCTION public.snapshot_storefront_ticket_design();

-- ===== 0025_organizer_invitations.sql =====
-- Invite new organizer accounts by email. Accepted invitations create a
-- pending organizer profile that an administrator must approve.

CREATE TABLE IF NOT EXISTS public.organizer_invitations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  email text NOT NULL,
  organizer_name text NOT NULL,
  organizer_slug text NOT NULL,
  token_hash text NOT NULL UNIQUE,
  invited_by uuid REFERENCES public.profiles (id) ON DELETE SET NULL,
  expires_at timestamptz NOT NULL,
  used_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT organizer_invitations_email_format CHECK (
    email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
  ),
  CONSTRAINT organizer_invitations_name_not_blank CHECK (length(btrim(organizer_name)) > 0),
  CONSTRAINT organizer_invitations_slug_format CHECK (
    organizer_slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'
  ),
  CONSTRAINT organizer_invitations_token_hash CHECK (token_hash ~ '^[a-f0-9]{64}$'),
  CONSTRAINT organizer_invitations_expiry_future CHECK (expires_at > created_at)
);

CREATE INDEX IF NOT EXISTS organizer_invitations_email_idx
  ON public.organizer_invitations (lower(email));
CREATE INDEX IF NOT EXISTS organizer_invitations_unused_idx
  ON public.organizer_invitations (expires_at) WHERE used_at IS NULL;

ALTER TABLE public.organizer_invitations ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS organizer_invitations_admin_select
  ON public.organizer_invitations;
CREATE POLICY organizer_invitations_admin_select
  ON public.organizer_invitations
  FOR SELECT TO authenticated USING (public.is_admin());

REVOKE ALL ON TABLE public.organizer_invitations FROM PUBLIC, anon;
GRANT SELECT ON TABLE public.organizer_invitations TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.create_organizer_invitation(
  p_email text,
  p_organizer_name text,
  p_organizer_slug text,
  p_token_hash text,
  p_expires_in interval DEFAULT interval '7 days'
)
RETURNS public.organizer_invitations
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_result public.organizer_invitations;
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_name text := btrim(coalesce(p_organizer_name, ''));
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Only administrators can invite organizers';
  END IF;
  IF v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' THEN
    RAISE EXCEPTION 'Enter a valid organizer email address';
  END IF;
  IF length(v_name) NOT BETWEEN 1 AND 160 THEN
    RAISE EXCEPTION 'Enter an organizer name between 1 and 160 characters';
  END IF;
  IF p_organizer_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' THEN
    RAISE EXCEPTION 'Invalid organizer URL slug';
  END IF;
  IF p_token_hash !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'Invalid invitation token hash';
  END IF;
  IF p_expires_in IS NULL OR p_expires_in <= interval '0' THEN
    RAISE EXCEPTION 'Invitation lifetime must be positive';
  END IF;
  IF EXISTS (SELECT 1 FROM auth.users WHERE lower(email) = v_email) THEN
    RAISE EXCEPTION 'This email already has an account; invite a new email address';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.organizer_invitations
    WHERE lower(email) = v_email
      AND used_at IS NULL
      AND expires_at > now()
  ) THEN
    RAISE EXCEPTION 'An active organizer invitation already exists for this email';
  END IF;
  IF EXISTS (SELECT 1 FROM public.organizers WHERE slug = p_organizer_slug)
    OR EXISTS (
      SELECT 1 FROM public.organizer_invitations
      WHERE organizer_slug = p_organizer_slug
        AND used_at IS NULL
        AND expires_at > now()
    )
  THEN
    RAISE EXCEPTION 'That organizer URL slug is already in use';
  END IF;

  INSERT INTO public.organizer_invitations (
    email, organizer_name, organizer_slug, token_hash, invited_by, expires_at
  )
  VALUES (
    v_email, v_name, p_organizer_slug, p_token_hash, auth.uid(), now() + p_expires_in
  )
  RETURNING * INTO v_result;
  RETURN v_result;
END;
$$;

CREATE OR REPLACE FUNCTION public.cancel_organizer_invitation(p_invitation_id uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Only administrators can cancel organizer invitations';
  END IF;

  DELETE FROM public.organizer_invitations
  WHERE id = p_invitation_id AND used_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'The unused organizer invitation could not be cancelled';
  END IF;
  RETURN true;
END;
$$;

CREATE OR REPLACE FUNCTION public.accept_organizer_invitation(
  p_user_id uuid,
  p_token_hash text
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_invitation public.organizer_invitations;
BEGIN
  IF p_token_hash !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'Invalid organizer invitation token';
  END IF;

  SELECT * INTO v_invitation
  FROM public.organizer_invitations
  WHERE token_hash = p_token_hash
  FOR UPDATE;

  IF NOT FOUND OR v_invitation.used_at IS NOT NULL OR v_invitation.expires_at <= now() THEN
    RAISE EXCEPTION 'Organizer invitation is invalid, expired, or already used';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM auth.users
    WHERE id = p_user_id AND lower(email) = lower(v_invitation.email)
  ) THEN
    RAISE EXCEPTION 'Organizer invitation email does not match this account';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.organizers WHERE owner_id = p_user_id
  ) THEN
    RAISE EXCEPTION 'This account already owns an organizer profile';
  END IF;

  UPDATE public.organizer_invitations
  SET used_at = now()
  WHERE id = v_invitation.id;

  BEGIN
    PERFORM set_config('app.organizer_invite_accepted', 'true', true);
    INSERT INTO public.user_roles (user_id, role_id, assigned_by)
    SELECT p_user_id, r.id, v_invitation.invited_by
    FROM public.roles r
    WHERE r.name = 'organizer'
    ON CONFLICT (user_id, role_id) DO NOTHING;
    PERFORM set_config('app.organizer_invite_accepted', '', true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('app.organizer_invite_accepted', '', true);
    RAISE;
  END;

  INSERT INTO public.organizers (
    owner_id, slug, name, contact_email, status, approval_status
  )
  VALUES (
    p_user_id, v_invitation.organizer_slug, v_invitation.organizer_name,
    v_invitation.email, 'pending', 'pending'
  );
  RETURN true;
END;
$$;

