CREATE OR REPLACE FUNCTION public.prevent_user_role_self_escalation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF TG_OP IN ('INSERT', 'UPDATE')
     AND NEW.user_id = auth.uid()
     AND NOT public.is_service_role()
     AND coalesce(current_setting('app.admin_invite_accepted', true), '') <> 'true'
     AND coalesce(current_setting('app.organizer_invite_accepted', true), '') <> 'true'
     AND EXISTS (
       SELECT 1 FROM public.roles r
       WHERE r.id = NEW.role_id AND r.name IN ('admin', 'organizer')
     ) THEN
    RAISE EXCEPTION 'Self-assignment of admin/organizer roles is not allowed';
  END IF;
  RETURN NEW;
END;
$$;

-- ===== 0026_admin_organizer_deletion.sql =====
-- Allow administrators to permanently remove an organizer only when no
-- operational, showcase, staff, or financial records depend on it.

CREATE OR REPLACE FUNCTION public.delete_organizer(p_organizer_id uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Only administrators can delete organizers';
  END IF;

  PERFORM 1
  FROM public.organizers
  WHERE id = p_organizer_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Organizer not found';
  END IF;

  IF EXISTS (SELECT 1 FROM public.events WHERE organizer_id = p_organizer_id)
     OR EXISTS (SELECT 1 FROM public.storefront_events WHERE organizer_id = p_organizer_id)
     OR EXISTS (SELECT 1 FROM public.organizer_staff WHERE organizer_id = p_organizer_id)
     OR EXISTS (SELECT 1 FROM public.organizer_payouts WHERE organizer_id = p_organizer_id)
     OR EXISTS (SELECT 1 FROM public.organizer_commissions WHERE organizer_id = p_organizer_id) THEN
    RAISE EXCEPTION
      'Cannot delete an organizer with linked events, showcase entries, staff assignments, payouts, or commissions';
  END IF;

  DELETE FROM public.organizers WHERE id = p_organizer_id;
  RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION public.delete_organizer(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.delete_organizer(uuid) TO authenticated;

-- ===== 0027_remove_organizer_subsystem.sql =====
-- Replace organizer accounts with administrator-entered event labels and
-- remove organizer accounts, invitations, staff, payout and commission data.

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM storage.objects WHERE bucket_id = 'organizer-logos') THEN
    RAISE EXCEPTION
      'Delete organizer logo files through Supabase Storage, then retry migration 0027';
  END IF;
  IF EXISTS (SELECT 1 FROM storage.buckets WHERE id = 'organizer-logos') THEN
    RAISE EXCEPTION
      'Delete the empty organizer-logos bucket through Supabase Storage, then retry migration 0027';
  END IF;
END;
$$;

