      to_jsonb(CASE ticket_design_style
        WHEN 'midnight' THEN '#7d64ff'
        WHEN 'festival' THEN '#ffbe5c'
        WHEN 'neon' THEN '#00e0be'
        ELSE '#f2c744'
      END)
    ),
